-- Restructures mother_activities content into granular fields for the activity detail UI.
-- Adds short_description (card teaser), steps (ordered how-to list), why_this (mother-facing
-- rationale), and a doctor-clearance flag + reusable clearance copy for moderate-effort
-- physical_recovery activities. The existing description column is untouched; these are
-- additive fields derived by splitting its content (plus progression_notes/source for context).

alter table mother_activities add column if not exists short_description text;
alter table mother_activities add column if not exists steps jsonb;
alter table mother_activities add column if not exists why_this text;
alter table mother_activities add column if not exists requires_doctor_clearance boolean not null default false;
alter table mother_activities add column if not exists clearance_copy text;

update mother_activities set
  short_description = v.short_description,
  steps = v.steps,
  why_this = v.why_this,
  requires_doctor_clearance = v.requires_doctor_clearance,
  clearance_copy = v.clearance_copy
from (values
  ('belly-breathing-m1', 'The foundation every other physical recovery step is built on — start here.', '["Lie on your back with your knees bent, one hand on your belly.", "Breathe in through your nose: your belly rises, your chest stays still.", "Breathe out slowly through pursed lips for 6 counts.", "Repeat 5 times, twice a day."]'::jsonb, 'Everything else in your recovery builds on this breath — it''s worth starting here before anything else.', false, null),
  ('foot-pumps-m1-c', 'Simple foot and ankle movements that lower your clot risk in the first week after surgery.', '["Lying or sitting, flex and point both feet for 30 seconds.", "Circle each ankle 5 times in each direction.", "Repeat every hour or two while you''re awake during the first week.", "If you were prescribed blood-thinning injections or compression stockings, complete the full course even once you feel well."]'::jsonb, 'Blood clots are a real risk after any birth, and a greater one after a caesarean — this keeps your circulation moving when you can''t yet walk much. Calf pain, swelling or warmth in one leg, or sudden breathlessness needs same-day attention.', false, null),
  ('feeling-your-body-down-there-m1', 'A no-effort body scan that reconnects you to your pelvic floor before any exercises begin.', '["Close your eyes and simply notice your pelvic floor, without trying to contract it.", "Imagine it softening and releasing downward.", "Don''t squeeze yet — just notice whatever you feel, including tightness, numbness or soreness."]'::jsonb, 'Noticing without effort is the right starting point before you begin any pelvic floor exercise — you''re rebuilding awareness first.', false, null),
  ('daily-oil-massage-m1-c', 'A warming daily massage for circulation and calm — just keep it away from your healing incision.', '["Have 15 minutes of warm oil massage on your arms, legs, shoulders and back.", "Use warm sesame oil, the traditional choice.", "Avoid the abdomen and anywhere near the incision until your doctor confirms it has fully healed, usually at the six-week check.", "Tell whoever is massaging you to skip the belly, since traditional maalish often includes it."]'::jsonb, 'This supports circulation, eases stiffness and calms your nervous system while your incision heals safely untouched.', false, null),
  ('healing-foods-m1-c', 'Traditional postpartum foods that genuinely help healing — plus two things surgery makes more important than usual.', '["Include gondh ke laddoo for tissue healing, ajwain water for digestion, methi for milk supply, and haldi doodh as an anti-inflammatory, alongside a balanced diet.", "Prioritise protein, which your wound needs to heal.", "Drink water freely rather than restricting it — after a caesarean, restricting water worsens constipation and gas pain, raises urine infection risk, and can reduce milk supply.", "If you had gestational diabetes or have diabetes, ask your doctor how many laddoos suit you, since they''re calorie and sugar dense."]'::jsonb, 'Traditional postpartum foods are nutritionally well designed and complement a balanced diet, but surgery raises your need for protein and fluids above the usual.', false, null),
  ('40-days-of-rest-m1-c', 'The traditional 40-day chilla is sound rest — with one change after a caesarean: don''t stay in bed.', '["Rest from housework, chores and responsibilities, and let others carry the load, as the chilla tradition intends.", "Get up and walk short distances several times a day, starting from the first day after surgery.", "If family members insist you stay lying down, let your doctor''s advice to walk take priority."]'::jsonb, 'Rest from chores is genuinely good for you, but after a caesarean, gentle movement lowers your risk of blood clots, eases gas pain and helps you heal — so take the rest, not the stillness.', false, null),
  ('warning-signs-to-act-on-m1', 'The symptoms after birth that need a same-day call to your doctor, not a wait-and-see.', '["Call your doctor or go to hospital immediately for bleeding that soaks a pad in an hour, or clots larger than a plum.", "Also call immediately for fever above 38C; a severe headache, blurred vision, or upper abdominal pain; pain, swelling, redness or warmth in one calf; chest pain or breathlessness; foul-smelling discharge; a wound that''s opening or has spreading redness; or feeling faint.", "Call even if you''re exhausted enough to talk yourself out of it."]'::jsonb, 'Knowing these signs matters more than any exercise in this plan — almost all of these complications are treatable when caught early, and calling anyway is the right call even when you''re too tired to.', false, null),
  ('what-normal-bleeding-looks-like-m1-c', 'What normal post-birth bleeding looks like after a caesarean, and the signs that mean it isn''t.', '["Expect lochia (post-birth bleeding) to be heaviest and bright red for the first few days, then turn pinkish or brown, then yellowish-white, over about six weeks.", "Expect it to be lighter overall than after a vaginal birth, and to briefly get heavier when you feed or first stand up.", "Use pads, not tampons or menstrual cups, until your doctor clears you.", "Watch for soaking a pad in an hour, clots larger than a plum, a foul smell, or bleeding turning heavy and bright red again after settling — these are warning signs."]'::jsonb, 'Knowing what''s normal for your bleeding lets you spot the warning signs early instead of worrying unnecessarily or missing something real.', false, null),
  ('when-your-milk-comes-in-m1-c', 'What to expect as your milk comes in after a caesarean, and the signs your baby is getting enough.', '["Expect colostrum for the first few days, then fuller milk around day two to five — it may take a little longer after a caesarean.", "Feed often, 8 to 12 times in 24 hours, and give plenty of skin-to-skin contact to help your milk along.", "Look for six or more wet nappies a day from around day five as a sign your baby is getting enough.", "If you''re worried, ask for a lactation consultant early rather than supplementing on a relative''s advice."]'::jsonb, 'Milk can take a little longer to come in after a caesarean, and that alone doesn''t mean anything is wrong — feeding often and skin-to-skin contact help it along.', false, null),
  ('engorged-or-painful-breasts-m1', 'What actually helps engorged, painful breasts — and the traditional habit that can make it worse.', '["Keep feeding your baby whenever they''re hungry.", "Don''t try to empty your breasts fully or pump extra — that can make the fullness worse.", "Use cold compresses between feeds and wear a comfortable, supportive bra.", "Avoid deep or vigorous breast massage, which can increase swelling and bruise the tissue.", "See a doctor the same day for a red, hot, painful area with fever or flu-like aches."]'::jsonb, 'Feeding on demand resolves engorgement naturally, while emptying extra or massaging vigorously — common traditional advice — can actually make it worse.', false, null),
  ('sad-days-or-something-more-m1', 'Telling baby blues apart from postpartum depression — and why it''s worth telling your doctor either way.', '["Notice if you have weepiness and mood swings in days 3 to 10 that resolve on their own — this is baby blues.", "Watch for 2 or more weeks of persistent sadness, hopelessness, difficulty bonding, or intrusive thoughts — this may be postpartum depression.", "Tell your doctor if you''re unsure which you''re experiencing."]'::jsonb, 'Postpartum depression responds very well to treatment, and there''s no shame in either baby blues or PPD — telling your doctor is how you find out which one you''re dealing with.', false, null),
  ('tell-your-birth-story-m1-c', 'Telling your birth story out loud, in your own words, to someone who just listens.', '["Tell one trusted person your birth story in your own words, without performing okayness.", "Ask them to simply listen, without advising or fixing anything."]'::jsonb, 'The story needs to leave your body through words before it can settle — this matters more, not less, if your caesarean was unplanned, an emergency, or not what you expected.', false, null),
  ('letting-people-help-m1', 'A short list that makes it easier to actually accept the help people are offering.', '["List 5 specific things you''ll accept help with this week — cooking, laundry, night feeds, older children.", "Share the list with the people around you."]'::jsonb, 'Most new mothers struggle to receive help even when it''s offered, because accepting feels like failing. It isn''t — help in this window is the difference between recovery and depletion.', false, null),
  ('saying-not-yet-to-visitors-m1', 'A simple message that lets you limit visitors without guilt.', '["Send a simple message to visitors: ''We''re resting and establishing feeding, we''ll welcome visitors from [date].''"]'::jsonb, 'You are allowed to limit visitors — excessive early visitors disrupt rest and create social obligation right when you''ve just been through a major physical event.', false, null),
  ('how-am-i-feeling-today-m1', 'One honest sentence a day about how you feel, not how the baby is.', '["Each evening, write or voice-note one sentence about how YOU feel — not the baby."]'::jsonb, 'One honest sentence a day works as both a mood record and a validation practice for yourself.', false, null),
  ('when-your-mind-needs-urgent-help-m1', 'The rare but urgent mental health signs after birth that need help the same day.', '["Get help the same day for thoughts of harming yourself or your baby, or feeling your baby would be better off without you.", "Also get help the same day for seeing or hearing things others don''t, feeling confused or that your thoughts aren''t your own, or a sudden inability to sleep even when the baby sleeps.", "Tell your partner, call your doctor, or go to a hospital — do not wait to see if it passes."]'::jsonb, 'Postpartum psychosis is rare but it''s a medical emergency and very treatable with prompt care — having these thoughts does not make you a bad mother and does not mean your baby will be taken from you.', false, null),
  ('skin-to-skin-time-m1', 'Simple skin-to-skin time — one of the best-evidenced things you can do for your baby and yourself.', '["Lay your baby bare-chested on your bare chest, covered with a warm cloth.", "Do this for as many hours of the day as you reasonably can."]'::jsonb, 'This is as close to settled science as developmental research gets: it regulates your baby''s temperature, helps feeding get established, lowers cortisol in both of you, and lays the deepest foundation of secure attachment.', false, null),
  ('talk-to-your-baby-m1', 'Simply talking to your baby, up close — the most familiar sound in their new world.', '["Talk to your baby at close range: narrate what you''re doing, sing, or read aloud.", "Keep it natural, not performative."]'::jsonb, 'Your baby has heard your voice for roughly 5 months in the womb — your specific voice and rhythm is the most familiar thing in their new world, and the continuity between womb and world.', false, null),
  ('looking-into-baby-s-eyes-m1', 'Simple eye contact at the exact distance your newborn can see clearly.', '["Hold your baby 20-25cm from your face — their clearest range in week 1.", "Look at them without trying to teach or stimulate anything."]'::jsonb, 'Mutual gaze between mother and newborn produces oxytocin in both of you at once. This isn''t preparation for a milestone — this is the relationship happening right now.', false, null),
  ('bedtime-song-m1', 'One song, sung every night — a sound anchor that will regulate your baby for years.', '["Choose one song that means something to you — a lori from your childhood or a folk song.", "Sing it every evening, the same song every night."]'::jsonb, 'You''re creating a sound anchor that will regulate your baby''s nervous system for years, while passing on a piece of your own inheritance.', false, null),
  ('who-wakes-up-when-m1', 'A written night-shift agreement that prevents the resentment of ''we''ll figure it out''.', '["Before the first night home, agree in writing who takes which window — for example, 9pm-1am one parent, 1am-6am the other."]'::jsonb, 'The specific structure matters less than having one at all — ''we''ll figure it out'' is the sentence most responsible for postpartum resentment.', false, null),
  ('we-re-in-survival-mode-m1', 'Naming the season out loud — couples who do this survive it better than those performing normalcy.', '["Say to each other, explicitly: ''We are in survival mode. This is temporary. We are doing this together.''"]'::jsonb, 'Couples who name the season survive it better than those who perform normalcy — survival mode has different rules: lower expectations, higher tolerance, more practical support.', false, null),
  ('our-help-word-m1', 'One agreed word that means ''I need relief right now, no questions asked''.', '["Agree on one word or phrase meaning ''I am at my limit and need relief right now, no questions asked.''", "When either of you uses it, the other takes over immediately — no negotiation."]'::jsonb, 'It''s a circuit breaker, not a competition — having the word ready matters more than how often you use it.', false, null),
  ('2-minute-check-in-m1', 'One daily question that isn''t about the baby — the entire relationship maintenance practice for month 1.', '["Once a day, ask each other: ''How are YOU?'' — a question that isn''t about the baby.", "Wait for the real answer. 2 minutes each."]'::jsonb, 'In month 1 this is the entire relationship maintenance practice, and that is enough.', false, null),
  ('doctor-visit-bring-questions-m2', 'Bringing written questions to your 6-week check so you actually get answers.', '["Write down your questions before the appointment: Am I cleared for pelvic floor work? For light exercise? Is my healing normal? Is my bleeding pattern normal?", "Also write down how you''ve actually been feeling and ask whether it''s within the expected range.", "Bring the list and ask everything on it."]'::jsonb, 'Most women leave this appointment without asking anything — the time is yours, and it''s easy to lose that if you don''t go in prepared.', false, null),
  ('short-walk-m2-c', 'Turning your short post-surgery walks into one continuous 10-minute daily walk.', '["Build your short walks into one continuous 10-minute flat walk daily.", "Go outdoors where possible, for the sunlight and air.", "Support your lower belly with a hand if you feel pulling at the scar."]'::jsonb, 'The goal this month is the daily habit, not pace or distance — sunlight, air and gentle movement all support your recovery.', false, null),
  ('fix-your-feeding-posture-m2', 'Fixing the hunched feeding posture that causes most postpartum neck and back pain.', '["Use a firm pillow to bring your baby up to breast height rather than leaning down to them.", "After each feed, do 5 backward shoulder rolls.", "Follow with a 20-second chest opener.", "Consider a session with a lactation consultant or physio if pain affects your feeding comfort."]'::jsonb, 'Most women develop neck and upper back pain from weeks of hunched feeding — this is one of the most preventable and most ignored postpartum physical issues.', false, null),
  ('neck-and-shoulder-stretch-m2', 'A quick stretch sequence to release the neck and shoulder tension that feeding builds up.', '["Drop your right ear toward your right shoulder, hold 20 seconds, then repeat on the left.", "Chin to chest, then slowly roll to the left, hold 20 seconds.", "Do 5 backward shoulder rolls.", "Clasp your hands behind your back and squeeze your shoulder blades together for 10 seconds."]'::jsonb, 'Do this after any prolonged feeding session to release the neck and shoulder tension that builds up from hours of hunching over your baby.', false, null),
  ('cat-cow-stretch-m2', 'A gentle all-fours stretch that restores spinal mobility after weeks of stillness.', '["Get on all fours.", "Inhale: drop your belly, lift your chin and tailbone.", "Exhale: round your spine toward the ceiling.", "Repeat for 8 slow rounds."]'::jsonb, 'This restores spinal mobility and reawakens your deep stabilisers after weeks of stillness.', false, null),
  ('mood-check-test-m2', 'A standard 10-question mood screen worth taking honestly at your 6-week check.', '["Take the 10-question self-assessment (Edinburgh Postnatal Depression Scale) honestly.", "If you score 10 or above, have a conversation with your doctor.", "Ask for the screen yourself if you aren''t offered it."]'::jsonb, 'PPD is not a character failure — it''s a medical condition with excellent treatment outcomes, and this screen is how it gets caught.', false, null),
  ('becoming-a-mother-named-m2', 'A short writing prompt that names the huge transition you''re actually going through.', '["Write for 10 minutes on: Who was I before? Who am I becoming?", "Also write: What feels lost? What feels gained that I didn''t expect?"]'::jsonb, 'Matrescence, the transition into motherhood, is as significant as adolescence and almost entirely unacknowledged — naming it reduces the sense that something is wrong with you.', false, null),
  ('how-much-sleep-am-i-missing-m2', 'Tracking your actual sleep for a week — the number is validating, not depressing.', '["Write down your sleep each day for 7 days: total hours, longest unbroken stretch, and number of interruptions.", "Compare your weekly total against 49 hours."]'::jsonb, 'Most mothers at month 2 run a 15-25 hour weekly deficit — seeing the number is validating: your fog and reactivity are the predictable result of severe deprivation, not weakness.', false, null),
  ('one-good-thing-today-m2', 'Naming one genuinely pleasurable thing each day, however tiny.', '["Each day, name one thing that gave you genuine pleasure, however tiny — a sip of chai, five minutes of sun, an unexpected song.", "Write it down."]'::jsonb, 'Actively hunting for joy rather than waiting for it is a learnable skill, and it''s particularly effective during sleep deprivation.', false, null),
  ('baby-s-first-real-smile-m2', 'Mirroring your baby''s first genuine social smile, warmly and right away.', '["When your baby smiles at you (usually between weeks 4-8), mirror it back immediately and warmly."]'::jsonb, 'This is the first deliberate social communication your child has ever made — your response teaches them that their signals produce responses, that they matter.', false, null),
  ('tummy-time-together-m2', 'Getting down on the floor at baby''s level during tummy time.', '["Lie face-down alongside your baby during tummy time.", "Keep your face in front of them at the same height, not looming from above."]'::jsonb, 'Your face at their level is the strongest possible motivation for them to lift their head.', false, null),
  ('copy-baby-s-sounds-m2', 'Echoing your baby''s sounds back to them — the earliest form of conversation.', '["When your baby makes any sound, respond with the same sound back.", "Then pause and wait to see if they repeat it."]'::jsonb, 'That repetition is the beginning of language, and the back-and-forth structure you create now becomes the template for every conversation they''ll have.', false, null),
  ('talk-through-every-task-m2', 'Narrating every routine task out loud, in whatever language feels natural.', '["Give a running commentary on everything you''re doing with your baby — dressing, feeding, bathing.", "Use your own words and languages naturally, without worrying about whether they understand yet."]'::jsonb, 'Your baby isn''t understanding words yet, but they''re cataloguing the sounds, rhythms and patterns of your language — every narrated routine is language architecture.', false, null),
  ('check-the-night-plan-m2', 'A 4-week check-in on your night-shift plan, before it breaks down.', '["Review the night-shift structure you agreed in month 1.", "Ask: what''s working? Who is more depleted?", "Adjust the plan based on the answers."]'::jsonb, 'A structure that worked in week 1 often needs recalibrating by week 4 as your baby''s pattern shifts — adjusting proactively beats waiting until someone hits breaking point.', false, null),
  ('5-minute-check-in-m2', 'Extending your daily check-in with a second question: one high, one hard.', '["Extend your daily check-in to 5 minutes.", "Add a second question, so you each share one high and one hard thing from the day."]'::jsonb, 'These two questions nightly are the minimum viable relationship maintenance for this period — they keep the emotional door open when exhaustion would otherwise close it.', false, null),
  ('one-kind-surprise-a-week-m2', 'One small, unasked act of care each week — not a chore, just a kindness.', '["Once a week, do one specific unasked thing for your partner that communicates care rather than chores — a warm drink, a lie-in, sitting with them through a hard feed."]'::jsonb, 'Small, consistent, unasked acts maintain the relationship when grand gestures aren''t possible.', false, null),
  ('longer-squeeze-holds-m3', 'Longer pelvic floor holds — and the breathing mistake that undoes them.', '["Do 5-second pelvic floor holds, 10 reps, twice daily.", "Keep breathing normally throughout — holding your breath increases intra-abdominal pressure instead of reducing it.", "Aim for a lift from below, not a squeeze from outside.", "See a women''s health physio if you still feel nothing."]'::jsonb, 'Each contraction should feel like a lift from below, not a squeeze from outside, and getting the breath right is what makes the exercise actually work.', false, null),
  ('deep-tummy-squeeze-m3', 'A deep core activation that must be restored before any other core work is safe.', '["Lie on your back with your knees bent.", "On the exhale, gently draw your lower belly inward and upward — a slow, controlled engagement, not sucking in.", "Hold 5 seconds, then release fully on the inhale.", "Repeat for 10 reps."]'::jsonb, 'This is the deepest core muscle layer, and it must be restored before any other core work is safe.', false, null),
  ('hip-lift-m3', 'Your first real strength exercise since birth — the start of rebuilding the posterior chain.', '["Lie on your back, knees bent, feet flat.", "Exhale, gently engage your pelvic floor, and lift your hips to a straight line from knees to shoulders.", "Hold 2 seconds, then lower slowly.", "Repeat for 10 reps."]'::jsonb, 'This is the first activity that goes beyond breathing and walking — the start of rebuilding the posterior chain.', false, null),
  ('20-minute-walk-m3', 'A daily 20-minute walk — still the most underrated postpartum exercise.', '["Walk for 20 minutes daily on flat ground.", "Focus on posture: shoulders back, head up, arms swinging."]'::jsonb, 'Walking gives you cardiovascular training, endorphins and better sleep, with no pelvic floor risk at this intensity.', false, null),
  ('wall-stand-m3', 'A wall exercise that closes the postural gap most new mothers don''t know they have.', '["Stand with your back against a wall, heels 5cm out, and flatten your back against the wall.", "Slowly slide your arms upward in a snow-angel motion, keeping contact with the wall throughout.", "Repeat for 10 reps."]'::jsonb, 'Most mothers find they can''t fully flatten their back against the wall — that gap is exactly what this closes.', false, null),
  ('evening-oil-rub-m3', 'A short evening oil massage ritual that signals to your nervous system the day is ending.', '["Sit on the edge of the bed.", "Massage warm sesame or coconut oil into your legs and feet for 10 minutes."]'::jsonb, 'This is both a continuation of traditional recovery practice and a predictable moment of self-care that costs almost no energy.', false, null),
  ('hair-falling-out-m3', 'Why your hair is suddenly falling out, and why it''s temporary.', '["Expect this shedding around three to four months after birth — it''s normal hormone-driven shedding, not true hair loss or something caused by breastfeeding.", "Ask your doctor to check you for anaemia if you also feel very tired or breathless."]'::jsonb, 'This is temporary — most women find their hair returns to its normal fullness by their baby''s first birthday.', false, null),
  ('mood-check-again-m3', 'A second mood check — PPD can emerge or peak at 3-4 months, not just in the first weeks.', '["Retake the Edinburgh Postnatal Depression Scale.", "Contact your doctor if you score 10 or above."]'::jsonb, 'PPD can emerge or peak at 3-4 months, when initial support has withdrawn but exhaustion has accumulated. You don''t have to be in crisis to deserve support.', false, null),
  ('planning-to-go-back-to-work-m3', 'A simple list that starts the work-return planning early, without deciding anything yet.', '["List what needs to be in place before returning to work: childcare, feeding plan, workplace flexibility, mental preparation.", "Just write the list — you don''t need to decide anything yet."]'::jsonb, 'The thinking time significantly reduces the anxiety of the transition itself.', false, null),
  ('who-am-i-now-m3', 'A writing prompt for the more durable, informative feelings that show up once the adrenaline wears off.', '["Write for 10 minutes on: What have I kept of who I was? What feels gone?", "Also write: What has surprised me about who I''m becoming?"]'::jsonb, 'Three months in, the initial adrenaline has worn off — the emotions that emerge now are more durable and more informative than the first-week ones.', false, null),
  ('what-s-bugging-me-m3', 'Naming 5 specific resentments before they accumulate and corrode quietly.', '["Write 5 specific resentments from this week — be concrete, like ''I resent that no one asks how I am.''"]'::jsonb, 'Naming specific resentments is the first step toward either addressing them or consciously accepting them — unnamed resentment just accumulates.', false, null),
  ('call-an-old-friend-m3', 'Reconnecting with one pre-baby friend, and talking about anything but babies.', '["Contact one friend from your life before the baby — not a fellow parent.", "Have a call or coffee, and talk about something entirely unrelated to babies."]'::jsonb, 'Adults who maintain non-parent connections through early parenthood have measurably better wellbeing outcomes — the effort is disproportionate to the reward, and worth it.', false, null),
  ('marking-40-days-m3', 'Marking the end of your 40-day chilla — not the end of recovery, but the end of the most protected period.', '["Mark the 40-day milestone, if you observed the chilla, with something meaningful: a meal you''ve been missing, a first outing, or a conversation with the women in your family about their own chilla."]'::jsonb, 'It isn''t the end of recovery — physical recovery takes 12 months — but it is the end of the most protected period, and that deserves acknowledgement.', false, null),
  ('back-and-forth-talk-game-m3', 'Counting the back-and-forth ''conversation'' turns with your baby — the most evidence-dense activity in early development.', '["During a calm, alert moment, respond to every sound or movement your baby makes.", "Pause and wait for their response each time.", "Count how many back-and-forth turns you sustain (a 3-month-old typically manages 3-5)."]'::jsonb, 'Thousands of these exchanges form the architecture for language and executive function — this is one of the most evidence-dense activities in early development.', false, null),
  ('black-and-white-card-game-m3', 'Simple high-contrast cards that give your baby''s developing visual cortex exactly what it needs.', '["Hold black-and-white cards or a book 20-25cm from your baby''s face.", "Move it slowly from left to right."]'::jsonb, 'You aren''t drilling flashcards — you''re providing the visual contrast that early visual cortex development specifically requires.', false, null),
  ('read-out-loud-m3', 'Reading anything at all out loud — the highest-value, lowest-effort activity on this list.', '["Read anything to your baby — a novel, a newspaper, a recipe.", "In a dual-language home, read in both languages."]'::jsonb, 'The vocabulary density of adult text is richer than children''s books — your baby isn''t learning words yet, they''re mapping the sound architecture of your language.', false, null),
  ('how-are-we-doing-really-m3', 'A scheduled 20-minute talk about the relationship itself, not who does more night feeds.', '["Schedule 20 minutes at a time when you''re not exhausted — not 11pm.", "Discuss one agenda item: how are we actually doing as a couple, and what''s been hardest?"]'::jsonb, 'Most couples haven''t had this conversation by month 3 — having it imperfectly is far better than not having it.', false, null),
  ('what-alone-time-do-i-need-m3', 'Writing down exactly how much alone time each of you needs, instead of assuming.', '["Each partner writes down how much alone time they need weekly, what it looks like, and what makes it possible.", "Share the lists with each other.", "Make one concrete arrangement from them."]'::jsonb, 'Most resentment about individual space comes not from a lack of goodwill but from the absence of an explicit conversation.', false, null),
  ('dead-bug-stretch-m4', 'Your first real core exercise since birth — stability without loading your midline.', '["Lie on your back, arms toward the ceiling, hips and knees at 90 degrees.", "Slowly lower one arm overhead and the opposite leg toward the floor while exhaling.", "Return slowly.", "Repeat 8 times on each side."]'::jsonb, 'This is the first real core exercise of postpartum recovery: it builds deep stability without loading the midline.', false, null),
  ('lift-like-a-lift-elevator-m4', 'A graded pelvic floor contraction that builds finer control than standard Kegels.', '["Imagine your pelvic floor as a lift with 3 floors.", "Contract to floor 1, then 2, then 3.", "Hold at the top for 8 seconds.", "Descend level by level.", "Repeat for 10 reps."]'::jsonb, 'This builds finer neuromuscular control than standard Kegels — the difference between gross and fine motor skill in the pelvic floor.', false, null),
  ('walk-fast-and-slow-m4', 'Interval walking that begins cardio rehab without the pelvic floor impact of running.', '["Walk 5 minutes easy to warm up.", "Alternate 3 minutes brisk with 2 minutes easy, twice.", "Finish with 5 minutes easy to cool down."]'::jsonb, 'The brisk intervals begin cardiovascular rehabilitation without the pelvic floor impact of running — build this aerobic base before building intensity.', true, 'Has your doctor cleared you for exercise? Stop if you feel pain, heaviness or leaking.'),
  ('bird-dog-stretch-m4', 'The ''anti-crunch'' — deep spinal stability work that doesn''t load your midline.', '["On all fours, extend one arm forward and the opposite leg back at the same time.", "Keep your spine neutral — no sagging, no rotation.", "Hold 3 seconds.", "Repeat 10 times on each side."]'::jsonb, 'This builds deep spinal stabilisers and gluteus medius without loading the midline.', true, 'Has your doctor cleared you for exercise? Stop if you feel pain, heaviness or leaking.'),
  ('one-leg-hip-lift-m4', 'Builds the pelvic stability you need for walking, stairs and carrying.', '["Lie on your back with your knees bent.", "Extend one leg out straight.", "Exhale and lift your hips using only the leg still on the ground.", "Hold for 2 seconds.", "Do 10 reps on each side, for 2 sets."]'::jsonb, 'This is significantly harder than the two-leg bridge, and it directly trains the pelvic stability you rely on for walking, stairs, and carrying your baby.', true, 'Has your doctor cleared you for exercise? Stop if you feel pain, heaviness or leaking.'),
  ('stretchy-band-arm-workout-m4', 'Your first upper-body resistance workout since birth, using just a resistance band.', '["Loop a resistance band around a door handle.", "Do rows: pull hands toward your lower ribs, elbows close, 15 reps.", "Do 15 bicep curls.", "Do 12 shoulder presses."]'::jsonb, 'Upper body strength atrophies significantly during the sedentary newborn weeks, and rebuilding it also restores the posture that feeding has bent.', true, 'Has your doctor cleared you for exercise? Stop if you feel pain, heaviness or leaking.'),
  ('what-my-body-has-done-m4', 'Three remarkable, functional things your body has done — not how it looks.', '["Write 3 things your body has done in 4 months that are remarkable — not how it looks, but what it did: grew a human, delivered one, is producing food, recovered from major physical trauma."]'::jsonb, 'Most postpartum body image work focuses on returning to a previous shape; this focuses on what the shape accomplished.', false, null),
  ('mood-check-at-4-months-m4', 'PPD often peaks at 3–4 months, not 3–4 weeks — worth checking in again now.', '["Retake the Edinburgh Postnatal Depression Scale.", "If you notice persistent low mood, loss of pleasure, anxiety, rage that feels disproportionate, or difficulty bonding, tell your doctor."]'::jsonb, 'The concern everyone shows you in the first weeks fades by now — which is exactly when postpartum depression often peaks. Checking in again catches what''s easy to miss.', false, null),
  ('get-ready-to-go-back-to-work-m4', 'Breaking your return to work into one small, concrete arrangement per week.', '["Make one concrete arrangement per week toward returning to work — a childcare trial run, a milk storage plan, a conversation with your employer, or a handover note."]'::jsonb, 'Breaking re-entry into micro-steps makes each one manageable — this transition is genuinely difficult in both logistical and emotional ways.', false, null),
  ('3-lines-every-morning-m4', 'Three lines before you pick up your phone — small enough to actually do every day.', '["Before picking up your phone, write 3 lines: one thing you''re grateful for, one feeling from yesterday, and one intention for today.", "Keep the journal beside your bed so starting takes no effort."]'::jsonb, 'The constraint is the practice — 3 lines is achievable every single day, which is what makes it work.', false, null),
  ('one-hour-just-for-me-m4', 'One protected hour, entirely for yourself, doing something that isn''t an errand.', '["Schedule one hour this week entirely for yourself — not errands.", "Protect it, and spend it on something that connects you to yourself outside the mother role: a show, a book, a walk with headphones, a coffee shop alone."]'::jsonb, 'You were a full person before — maintaining that personhood takes active protection, not just hope.', false, null),
  ('name-the-feeling-m4', 'Naming a strong feeling out loud within 60 seconds of noticing it.', '["When you feel something strong, name it within 60 seconds, aloud or in writing — for example, ''I am feeling overwhelmed right now.''"]'::jsonb, 'Named emotions carry less neurological charge than unnamed ones; labelling activates the prefrontal cortex and dampens amygdala reactivity.', false, null),
  ('longer-babble-chat-m4', 'A dedicated back-and-forth chat that grows the sounds your baby''s starting to babble.', '["Set aside a dedicated 15-minute session with your baby.", "Respond to every sound they make with a vocal turn of your own.", "Hold the pause for a full 10 seconds before responding, to give them room to answer."]'::jsonb, 'By month 4 your baby''s babbling is expanding — ba, da, ma — not words yet, but exactly the sounds first words will be built from.', false, null),
  ('explore-an-object-m4', 'Letting your baby freely explore simple household objects, while you just observe.', '["Offer your baby 3-4 simple household objects — a wooden spoon, a metal cup, a cloth, a plastic bottle.", "Let them handle each one without directing.", "Observe what they do: which do they mouth, bang, or pass between hands?"]'::jsonb, 'At 4 months babies are beginning to understand objects as having consistent properties — your observation without intervention is the gift.', false, null),
  ('picture-book-time-m4', 'Introducing picture books — not to drill vocabulary, but to build the association between reading and closeness.', '["Introduce board books with 1-2 high-contrast images per page.", "Read slowly: point to the image, name it, pause."]'::jsonb, 'You''re introducing that images represent real things, and that reading is shared, pleasurable, and associated with closeness — that association is being formed right now.', false, null),
  ('5-minute-nightly-chat-m4', 'A formalised 5-minute nightly chat: one high, one hard, one appreciation.', '["Before sleep, spend 5 minutes sharing: one high, one hard, and one appreciation for your partner."]'::jsonb, 'This simple structure done nightly is the most sustainable relationship maintenance available in the first year — it requires almost no energy.', false, null),
  ('date-night-at-home-m4', 'You don''t need to go out to have a date — just intention, novelty, and 60 phone-free minutes.', '["Wait until baby''s asleep.", "Set the table, and cook or order something deliberately.", "Put phones away for 60 minutes."]'::jsonb, 'Month 4 is the first point where this is realistically possible again — don''t wait for a perfect moment that may not come.', false, null),
  ('how-are-we-doing-round-2-m4', 'Returning to the month 3 relationship conversation — what''s shifted, what''s still hard.', '["Return to the month 3 conversation.", "Ask: what''s shifted? What''s better? What''s still hard? What do you each need in the next month?"]'::jsonb, 'This informal quarterly relationship review is more useful than a year of implicitly hoping things improve on their own.', false, null),
  ('quick-squeezes-m5', 'Fast pelvic floor flicks that train the fibres responsible for continence during a sneeze or cough.', '["After 10 elevator lifts, do 10 quick flicks: contract and release as fast as you can.", "See a women''s health physiotherapist if you can''t feel a clear distinction between the slow holds and fast flicks."]'::jsonb, 'These train the fast-twitch fibres responsible for continence during a sneeze, cough, or jump.', false, null),
  ('squats-m5', 'A functional squat, with baby as your workout buddy.', '["Stand with feet hip-width apart, toes slightly out.", "Lower until your thighs approach parallel, then rise through your heels.", "Do 15 reps, 2 sets.", "Hold your baby at chest height and narrate ''down, up!'' as you go."]'::jsonb, 'This is a functional, compound movement appropriate for most women at month 5 — and your baby''s delight makes 2 sets feel shorter.', true, 'Has your doctor cleared you for exercise? Stop if you feel pain, heaviness or leaking.'),
  ('30-minute-walk-with-fast-bits-m5', 'A structured 30-minute interval walk — the intensity ceiling before you assess running readiness.', '["Walk 5 minutes easy to warm up.", "Alternate 4 minutes brisk with 2 minutes easy, three times.", "Walk 5 minutes easy to cool down."]'::jsonb, 'This is a meaningful cardiovascular session, and for most women it''s the appropriate intensity ceiling before assessing readiness to run.', true, 'Has your doctor cleared you for exercise? Stop if you feel pain, heaviness or leaking.'),
  ('cat-cow-and-twist-m5', 'Cat-cow plus a thoracic twist that counteracts the hunch of feeding and carrying.', '["Do 8 cat-cow rounds.", "Slide one hand under your body and reach through to the other side, following with your gaze.", "Hold 5 breaths.", "Repeat 5 times on each side."]'::jsonb, 'This thoracic rotation directly counteracts the posture pattern of feeding, carrying, and device use.', false, null),
  ('getting-stronger-step-by-step-m5', 'A simple 4-week strength progression across the exercises you''ve already learned.', '["Weeks 1-2: do 3 sets of 10 of glute bridges, bird dogs, dead bugs, band rows, band shoulder press and bicep curls.", "Weeks 3-4: progress to 3 sets of 12, or add slightly more resistance.", "Log your sessions."]'::jsonb, 'Progressive overload is the mechanism behind getting stronger, and the written record makes progress visible and the practice sustainable.', true, 'Has your doctor cleared you for exercise? Stop if you feel pain, heaviness or leaking.'),
  ('what-surprised-me-about-myself-m5', 'What''s genuinely surprised you about yourself as a mother, five months in.', '["Write for 10 minutes about what has genuinely surprised you about yourself as a mother — the capacity you didn''t know you had, the limits you didn''t expect, the love that arrived differently than you imagined."]'::jsonb, 'Five months is enough time for real self-knowledge to have formed — document it now, before it becomes assumed and forgotten.', false, null),
  ('one-hour-no-phone-m5', 'One phone-free hour each evening, just to let your nervous system be unstimulated.', '["Put your phone in another room for one hour each evening."]'::jsonb, 'This isn''t about productivity — it''s about letting your nervous system be genuinely unstimulated, which almost certainly hasn''t happened in 5 months.', false, null),
  ('write-down-my-anger-m5', 'A timed 10-minute rage journal — write every resentment without stopping or editing.', '["Set a timer for 10 minutes.", "Write every resentment and frustration about this season — your body, sleep, loss of freedom, specific people or situations — without stopping or editing.", "Destroy the page afterward, or keep it — your choice."]'::jsonb, 'Naming specific angers is the first step to processing rather than suppressing them.', false, null),
  ('one-goal-just-for-me-m5', 'One personal goal for the next 6 months that belongs only to you.', '["Name one thing you want to do in the next 6 months that is yours, not as a mother or partner — professional, creative, learning, or fitness.", "Write it down.", "Tell one person about it."]'::jsonb, 'Naming a personal goal and making it social is the first step toward it not being consumed by early parenting.', false, null),
  ('rolling-games-m5', 'Rolling around on the floor with your baby, to make movement feel like play.', '["Place a toy just out of reach to the side to encourage your baby to roll toward it.", "Get down on the floor and roll alongside them yourself."]'::jsonb, 'Your presence on the floor, rolling too, communicates that movement is joyful, not a task — and a full adult roll genuinely makes babies laugh.', false, null),
  ('same-book-5-days-m5', 'Reading the same book 5 days running — watching memory form, visibly.', '["Choose one book and read it at the same time for 5 days running.", "Introduce a new book afterward."]'::jsonb, 'Repetition first, novelty second mirrors how language learning actually works — by day 5 you''ll see recognition responses that were absent on day 1: that''s memory forming.', false, null),
  ('touch-and-feel-walk-m5', 'A walk where your baby touches one new texture, named in a few words.', '["Carry your baby facing outward during a walk.", "Let their hand briefly touch one texture — tree bark, a gate, a wall, a flower.", "Describe each texture in 2-3 words as they touch it."]'::jsonb, 'The pathway being built is sensation to language to understanding — you''re laying the first layer of that connection.', false, null),
  ('peek-a-boo-m5', 'Classic peek-a-boo — the earliest form of object permanence, dressed up as a game.', '["Hide behind your hands.", "Reveal yourself with sound and expression.", "Repeat, enthusiastically."]'::jsonb, 'Their delight isn''t just happiness — it''s the neurological reward of a prediction coming true.', false, null),
  ('weekly-us-check-m5', 'A weekly 20-minute ''us'' check-in that prevents unexpressed needs from turning into resentment.', '["Once a week, for 20 minutes while baby is asleep or with another caregiver, ask each other: how am I doing, how are you doing, what do we need from each other this week, what''s working and what needs adjusting?"]'::jsonb, 'This prevents the accumulation of unexpressed needs that becomes resentment — and it''ll still be relevant at month 60.', false, null),
  ('something-fun-to-plan-m5', 'Planning something fun 3-6 months out — re-establishing you as partners in a shared life.', '["Have one conversation about something 3-6 months ahead that you both want — a short trip, a dinner, a home project, a festival together."]'::jsonb, 'Future-orientation creates hope in the present and re-establishes you as partners in a shared life rather than co-managers of an ongoing emergency.', false, null),
  ('standing-belly-breathing-m6', 'Taking your month-1 breathing foundation from lying down to standing up.', '["Progress your breathing practice from lying down, to seated, to standing.", "One hand on your belly, breathe in through your nose so your belly rises.", "Breathe out through pursed lips for 6 counts.", "Repeat for 10 breaths."]'::jsonb, 'Breathing well in an upright, loaded position is what transfers to real life: lifting, carrying, and exercise.', false, null),
  ('squeezes-in-every-position-m6', 'Training your pelvic floor in four positions, not just lying down.', '["Do 10 eight-second holds plus 10 quick flicks.", "Across the week, do this in four positions: lying, sitting, standing, and squatting."]'::jsonb, 'Your pelvic floor must work against gravity in real life, so training it only lying down transfers poorly.', false, null),
  ('cat-cow-with-baby-watching-m6', 'Cat-cow with baby watching — mobility for you, face-to-face play for them.', '["Put baby on the mat in front of you.", "Inhale, drop your belly, lift your chin, and make eye contact with baby.", "Exhale, round your spine toward the ceiling.", "Peek at baby on each cat pose.", "Repeat for 10 slow rounds."]'::jsonb, 'This gives you gentle spinal mobilisation while giving your baby face-to-face social interaction at the same time.', false, null),
  ('hip-lift-more-reps-m6', 'A higher-rep hip lift, with a reminder about where the squeeze should happen.', '["Feet flat, exhale, and lift your hips to a straight line from knees to shoulders.", "Hold 2 seconds, squeezing your glutes, not your jaw.", "Lower slowly.", "Repeat for 12 reps, 2 sets."]'::jsonb, 'Building rep volume here keeps rebuilding the posterior chain strength you started in month 3.', false, null),
  ('morning-walk-with-baby-m6', 'A conversational-pace morning walk — medicine for you, vestibular input for baby.', '["Walk for 20 minutes at a pace where you can hold a conversation.", "Focus on a heel-to-toe gait and swinging arms."]'::jsonb, 'This is medicine: cortisol regulation, vitamin D and joint mobilisation for you, and vestibular input for your baby.', false, null),
  ('wrist-stretch-m6', 'A wrist stretch that prevents and treats the wrist pain that''s close to epidemic among new mothers.', '["Extend one arm, palm up, and gently pull your fingers toward you. Hold 20 seconds.", "Turn palm down and hold 20 seconds.", "Circle your wrist in each direction.", "Repeat on the other side."]'::jsonb, 'De Quervain''s tenosynovitis — wrist pain from lifting and holding a baby — is close to epidemic among new mothers; this is both prevention and treatment.', false, null),
  ('letter-about-your-birth-m6', 'A private letter to yourself about your birth — one of the most underused processing tools there is.', '["Write a letter to yourself about your birth: what happened, what it felt like, what surprised you, what you wish had been different.", "Keep it private — it''s not for anyone else."]'::jsonb, 'This is one of the most underused postpartum processing tools, especially for mothers who feel their birth needs explaining. It doesn''t.', false, null),
  ('who-i-am-a-map-m6', 'A simple identity map — and circling the 2 parts of yourself worth nourishing this month.', '["On a blank page, write ''I am'' in the centre.", "Around it, write every identity you hold: daughter, professional, friend, partner, reader, cook, mother.", "Notice which feel distant right now.", "Circle 2 you want to actively nourish this month alongside motherhood."]'::jsonb, 'Those 2 identities matter — actively nourishing them alongside motherhood is how you stay a full person.', false, null),
  ('lie-down-while-baby-naps-m6', 'Lying flat and quiet during baby''s nap, even if you don''t actually sleep.', '["When baby naps, lie flat in a quiet room, phone away.", "Set a gentle 20-minute alarm so you can rest without watching the clock."]'::jsonb, 'Being horizontal in silence is restorative even without sleep — this is not laziness, it''s the biology of recovery.', false, null),
  ('evening-mood-score-m6', 'A nightly 1-10 mood score that reveals your real patterns over six weeks.', '["Each evening, rate your mood from 1 to 10.", "Add one sentence on what most affected it that day."]'::jsonb, 'Over 6 weeks the patterns become clearly visible — sleep, exercise, isolation and social contact all show up in the data, and knowledge reduces self-blame.', false, null),
  ('no-phone-evening-hour-m6', 'One defended phone-free hour each evening, to let your attention finally rest.', '["Pick one hour each evening and defend it.", "Put your phone in another room for that hour."]'::jsonb, 'A depleted nervous system is not a parenting style — it''s a medical condition, and this gives it a chance to rest.', false, null),
  ('one-friend-call-a-week-m6', 'A scheduled weekly friend call, about anything except motherhood.', '["Schedule one 20-minute call with a friend this week — don''t wait to feel like it.", "Talk about anything other than motherhood."]'::jsonb, 'Sustained adult friendship in the early parenting years requires deliberate maintenance — the effort is asymmetric, but the return isn''t.', false, null),
  ('10-minutes-alone-every-day-m6', 'Ten minutes alone, once a day, anywhere at all.', '["Once a day, be alone for 10 minutes, anywhere — toilet, garden, balcony, a bedroom with the door shut."]'::jsonb, 'A depleted caregiver cannot give what they don''t have — protect this with the same certainty as a feed.', false, null),
  ('gentle-yoga-with-baby-m6', 'A gentle 5-pose yoga sequence with baby on the mat beside you.', '["Place baby on the mat in front of you.", "Move through five poses, five breaths each: forward fold facing baby, child''s pose at their eye level, seated side stretch, supine twist, and savasana with baby on your chest."]'::jsonb, 'This gives you restoration and bonding at once — not exercise, not performance, just time together.', false, null),
  ('one-feed-fully-present-m6', 'One fully present feed a day — phone down, eyes on baby''s face.', '["Once per day during a feed, put your phone down and skip the podcast.", "Keep your eyes on your baby''s face.", "Notice how they swallow, how their hands move, when their eyes close."]'::jsonb, 'This isn''t a task to optimise — it''s the relationship happening in real time, and what you give attention to grows.', false, null),
  ('walk-and-describe-the-world-m6', 'Narrating the world on a walk — language for baby, mindfulness for you.', '["Carry baby facing out during a walk.", "Narrate what you see, smell and hear.", "Stop at interesting things and describe them in 3 words — ''rough, brown, hard.''"]'::jsonb, 'This is language development for your baby and a mindfulness practice for you at the same time — the double benefit isn''t accidental.', false, null),
  ('evening-song-m6', 'The same evening song, every night, during bath or the last feed.', '["Choose one song — a lori or folk song that matters to you.", "Sing it every evening during bath or the last feed, same song, same time."]'::jsonb, 'Predictability regulates your baby, and the singing regulates you — this becomes a shared memory.', false, null),
  ('skin-to-skin-nap-m6', 'A weekly skin-to-skin nap together, long after the newborn stage.', '["Once a week, during a daytime nap, lie with baby on your chest, skin to skin.", "Rest together."]'::jsonb, 'Oxytocin goes up and cortisol goes down for both of you — this doesn''t stop being effective after the newborn stage, it works all year.', false, null),
  ('chores-with-baby-worn-m6', 'Wearing baby in a carrier while you get household tasks done.', '["Wear your baby in a carrier for 20 minutes of household tasks."]'::jsonb, 'Your baby gets vestibular input, warmth and closeness while you get tasks done and oxytocin — carrying does not spoil them.', false, null),
  ('talk-about-something-else-m6', 'Ten minutes a day talking about anything except the baby.', '["Talk for 10 minutes daily about something with nothing to do with the baby — a news story, a show, a memory, a ridiculous hypothetical."]'::jsonb, 'You were full people before you were parents — keeping that alive takes deliberate daily practice.', false, null),
  ('weekly-date-at-home-m6', 'A weekly at-home date — intention and attention matter more than the venue.', '["Once a week, after baby''s asleep, set the table and light a candle.", "Cook or order something deliberately.", "Put phones away for 90 minutes."]'::jsonb, 'You don''t need to go out — you need intention, novelty, and mutual attention. Environment is secondary.', false, null),
  ('say-thanks-at-dinner-m6', 'One specific appreciation at dinner, about the person, not the parenting.', '["Each person names one thing they appreciate about the other — about them as a person, not their parenting.", "Be specific and observed, like ''I noticed you stayed calm during the difficult doctor visit.''"]'::jsonb, 'This is attachment maintenance for the couple.', false, null),
  ('lift-like-a-lift-harder-m7', 'A harder elevator-lift progression, laying groundwork for months 8-12.', '["Contract your pelvic floor through three floors.", "Hold 5 seconds at the top.", "Descend floor by floor.", "Repeat for 10 reps."]'::jsonb, 'This builds finer neuromuscular control than standard Kegels, laying the groundwork for the functional demands of months 8-12.', false, null),
  ('dead-bug-harder-version-m7', 'A continued dead bug progression for deep core stability — fundamentally different from a crunch.', '["Arms toward the ceiling, hips and knees at 90 degrees.", "Lower one arm overhead and the opposite leg while exhaling.", "Return slowly.", "Repeat 8 times on each side."]'::jsonb, 'This builds deep core stability, fundamentally different from crunches and precisely what postpartum recovery needs.', false, null),
  ('squats-holding-baby-m7', 'Squats with baby along for the ride — a gentle bounce for them, leg strength for you.', '["Hold baby facing outward at chest height.", "Feet hip-width, toes slightly out, lower until your thighs approach parallel.", "Rise through your heels.", "Do 15 reps, 2 sets, narrating as you go."]'::jsonb, 'Your baby gets a gentle ride while your legs and glutes rebuild.', true, 'Has your doctor cleared you for exercise? Stop if you feel pain, heaviness or leaking.'),
  ('30-minute-walk-fast-and-slow-m7', 'A 30-minute walk with two short bursts too brisk to sing through.', '["Walk for 30 minutes.", "At the 10-minute and 20-minute marks, walk briskly for 2 minutes — fast enough that you couldn''t sing."]'::jsonb, 'These brief bursts restore cardiovascular fitness without the pelvic floor load of running — build the habit before the intensity.', true, 'Has your doctor cleared you for exercise? Stop if you feel pain, heaviness or leaking.'),
  ('twist-stretch-m7', 'A thoracic twist that counteracts months of rounding from feeding and carrying.', '["On all fours, slide one hand under your body and reach through, letting your top arm follow.", "Feel your thoracic spine open.", "Hold 5 breaths.", "Repeat 5 times on each side."]'::jsonb, 'This counteracts seven months of rounding from feeding and carrying.', false, null),
  ('one-hour-being-just-me-m7', 'Once this week, doing something you did before you were a mother — guilt or not.', '["Once this week, do something you did before you were a mother: read for pleasure, watch something you care about, cook something elaborate, shop alone, or walk without purpose.", "Do it even if you feel guilty."]'::jsonb, 'Identity recovery requires practice, not permission.', false, null),
  ('count-my-missing-sleep-m7', 'Tracking your real sleep deficit for a week — not to fix it today, just to see it clearly.', '["Record your actual sleep each day for 7 days.", "Note your longest unbroken stretch each night.", "Calculate your weekly deficit against 49 hours."]'::jsonb, 'Most mothers badly underestimate the deficit, and seeing the data reduces self-blame for fog and reactivity.', false, null),
  ('name-the-feeling-and-the-need-m7', 'Naming the feeling, then naming the need — turning the practice from expressive to functional.', '["When you feel something strong, name it within 60 seconds, aloud or in writing.", "Add: ''and what I need right now is...''"]'::jsonb, 'This extension turns naming from expressive into functional — it gives you something to act on, not just something to notice.', false, null),
  ('dance-with-baby-m7', 'Dancing freely with baby close, just because the song is good.', '["Put on a song you love.", "Wear your baby close.", "Dance freely and unreservedly in your own home."]'::jsonb, 'Your baby gets vestibular input, your heartbeat, and movement that''s joyful rather than purposeful — and you get to be in your body in a way that isn''t remedial.', false, null),
  ('15-minutes-of-back-and-forth-play-m7', 'Fifteen minutes of fully following your baby''s lead, with devices away.', '["Put devices away.", "Put baby on the mat with 2 toys.", "Follow their lead entirely for 15 minutes — when they look, look back; when they reach, respond; when they babble, babble back."]'::jsonb, 'By wide research consensus, this is the most important parenting activity available to you.', false, null),
  ('peek-a-boo-new-ways-m7', 'Varying peek-a-boo to test whether object permanence has really taken hold.', '["Hide behind a cloth, a cushion, or a door.", "Return each time with a different expression or sound."]'::jsonb, 'The variation tests whether the concept of your return has generalised beyond one script — the anticipatory smile before you reappear is the milestone moment.', false, null),
  ('nightly-chat-plus-a-thank-you-m7', 'Your nightly debrief, plus one specific observed appreciation.', '["Continue the 5-minute nightly debrief.", "Add one specific observed appreciation, like ''I noticed you took the morning feed so I could sleep in.''"]'::jsonb, 'Specific over general, always — a concrete appreciation lands differently than a vague one.', false, null),
  ('check-if-alone-time-is-happening-m7', 'An honest audit of whether your alone-time arrangements are actually happening.', '["Check honestly whether the alone-time arrangements you made in months 3 and 5 are actually happening.", "Adjust rather than let them quietly lapse."]'::jsonb, 'Most couples make the agreement and never audit it — checking honestly is what keeps it real.', false, null),
  ('wide-squat-with-baby-m8', 'A wide squat that targets the inner thighs and glutes most exercises miss.', '["Feet wide, toes at 45 degrees, baby held close to your chest.", "Lower into a wide squat and pulse 10 times at the bottom.", "Rise.", "Repeat for 3 sets of 10."]'::jsonb, 'This targets the inner thighs and gluteus medius — muscles usually underloaded in standard squats and critical for pelvic stability and knee health.', true, 'Has your doctor cleared you for exercise? Stop if you feel pain, heaviness or leaking.'),
  ('stretchy-band-rowing-m8', 'Resistance band rows that rebuild the upper-back strength months of feeding has suppressed.', '["Loop a band around a door handle at chest height.", "Hold one end in each hand and step back.", "Pull your hands toward your lower ribs, elbows close to your body.", "Do 15 reps, 3 sets."]'::jsonb, 'This rebuilds the upper back strength that months of feeding posture has progressively suppressed.', true, 'Has your doctor cleared you for exercise? Stop if you feel pain, heaviness or leaking.'),
  ('35-minute-walk-fast-and-slow-m8', 'A longer structured interval walk, building your aerobic base before adding intensity.', '["Walk 5 minutes easy to warm up.", "Alternate 3 minutes brisk with 2 minutes easy, five times.", "Walk 5 minutes easy to cool down."]'::jsonb, 'This is structured cardiovascular rehabilitation without the impact load of running — build the aerobic base before the intensity.', true, 'Has your doctor cleared you for exercise? Stop if you feel pain, heaviness or leaking.'),
  ('open-your-chest-lying-down-m8', 'A passive chest-opening stretch that undoes months of forward feeding posture.', '["Lie on your back along a rolled blanket running the length of your spine.", "Arms out to the sides, palms up, eyes closed.", "Stay for 3-5 minutes."]'::jsonb, 'This passive chest opening undoes months of forward posture — possibly the most underrated recovery tool available.', false, null),
  ('thank-your-body-m8', 'Three remarkable things your body has done in 8 months — not how it looks.', '["Stand in front of a mirror for 5 minutes.", "Say aloud or write 3 things your body has done in 8 months that are remarkable — not how it looks, but what it did."]'::jsonb, 'It grew, delivered, sustained, and held a human being through their most vulnerable phase. That is extraordinary.', false, null),
  ('what-i-miss-from-before-m8', 'Writing honestly about what you miss from before — without guilt or explaining yourself.', '["Write for 5 minutes about what you miss from your pre-baby life.", "Don''t censor it, feel guilty about it, or explain yourself."]'::jsonb, 'Missing things does not mean loving your baby less — it means you were a full person before, and still are. Grief and love coexist.', false, null),
  ('list-everything-that-s-annoying-me-m8', 'A timed 10-minute list of everything that''s annoying you right now.', '["Set a timer for 10 minutes.", "Write every resentment and frustration — your partner, your body, sleep, loss of freedom, mess, being touched all day — without stopping or editing.", "Share relevant items at your next relationship check-in, as information, not accusation."]'::jsonb, 'Naming specific angers is the first step to either addressing them or consciously accepting them.', false, null),
  ('getting-the-work-plan-ready-m8', 'A simple list of what would make returning to work easier — no decisions needed yet.', '["List what would make returning to work easier — flexible hours, childcare logistics, mental preparation, backup plans.", "Just list, don''t decide anything yet."]'::jsonb, 'Most mothers find that thinking through options in advance halves the anxiety of the transition.', false, null),
  ('let-baby-lead-the-play-m8', 'Thirty minutes of floor time with no agenda — just following baby''s attention.', '["Spend 30 minutes on the floor with baby, with no agenda and no planned activities.", "Follow their attention entirely — sit, be available, respond only when invited."]'::jsonb, 'Child-initiated play in a responsive environment is the richest developmental context that exists, and it asks less of you than any structured activity.', false, null),
  ('longer-bath-time-m8', 'Stretching bath time out into a slow, calming ritual rather than a hygiene task.', '["Extend bath time to 20 minutes.", "Slow it down with warm water, simple toys, face-to-face time, and singing."]'::jsonb, 'This is one of the most regulated, multi-sensory, calming experiences you can give a baby, and a naturally de-escalating window for you both at day''s end.', false, null),
  ('first-time-out-without-baby-m8', 'Your first 2-hour outing without baby — the goal is the experience, not the activity.', '["Plan one 2-hour outing without baby — dinner, a walk, a film, anything."]'::jsonb, 'The goal isn''t the activity — it''s the experience of being two people in the world without the parenting role immediately active, and noticing if that feels harder than expected is part of it.', false, null),
  ('talk-about-next-year-m8', 'One conversation about something 12 months ahead, as partners in a shared project.', '["Have one conversation about something 12 months ahead — a holiday, a change at home, a professional plan, a family vision."]'::jsonb, 'Future-planning together reactivates the sense of being partners in a shared project — the frame that newborn survival mode suspends entirely.', false, null),
  ('write-a-thank-you-note-m8', 'A handwritten 3-sentence thank-you note for your partner, not just spoken words.', '["At the end of this month''s check-in, write your partner a 3-sentence appreciation on paper."]'::jsonb, 'Handwritten appreciation is qualitatively different from spoken — it''s kept, re-read, and carries weight that an exhausted 11pm conversation cannot.', false, null),
  ('easy-plank-on-knees-m9', 'A gentle knee plank — your safe entry back into core work after a caesarean.', '["Forearms and knees on the floor, hips level.", "Hold for 10 seconds, rest 30.", "Do 5 reps.", "Watch for any midline doming/coning or scar pulling — if either appears, return to dead bugs for 2 more weeks.", "Only begin once you can do 12 controlled dead bugs with no doming."]'::jsonb, 'Your abdominal wall was surgically divided, so this starts a month later than it would after a vaginal birth — rushing to a full plank before it''s ready can make things worse.', true, 'Has your doctor cleared you for exercise? Stop if you feel pain, heaviness or leaking.'),
  ('lunges-m9', 'Lunges that rebuild the single-leg strength stairs and carrying demand every day.', '["Step forward into a lunge, back knee hovering near the floor.", "Hold 2 seconds.", "Drive back through your front heel.", "Repeat 12 times on each side, 2 sets.", "Add baby on your hip if comfortable."]'::jsonb, 'This rebuilds the single-leg strength that stairs, carrying, and everyday movement demand.', true, 'Has your doctor cleared you for exercise? Stop if you feel pain, heaviness or leaking.'),
  ('side-leg-lift-m9', 'A side leg lift targeting the glute muscle almost every mother is weak in postpartum.', '["Lie on your side and lift your top leg straight to 45 degrees.", "Pause at the top, then lower slowly.", "Repeat 15 times on each side, 2 sets."]'::jsonb, 'Gluteus medius is critical for pelvic stability, knee tracking, and back health — it''s rarely targeted by standard exercises and almost universally weak postpartum.', false, null),
  ('head-to-toe-stretch-m9', 'A 15-minute nightly stretch sequence that restores full range of motion.', '["Each night, move through: cat-cow, child''s pose, a hip flexor stretch, supported pigeon, a supine twist on both sides, and a chest opener on a bolster.", "Spend about 15 minutes total."]'::jsonb, 'By month 9, restoring full range of motion matters as much as building strength — this is a permanent asset, not a temporary routine.', false, null),
  ('arm-and-shoulder-workout-m9', 'A band or light dumbbell workout that rebuilds the upper body strength and posture newborn months took.', '["Using a band or light dumbbells, do a shoulder press, bent-over row, and bicep curl.", "Do 3 sets of 12 of each."]'::jsonb, 'Upper body strength atrophied during the sedentary newborn period, and rebuilding it also rebuilds the posture that months of feeding and carrying have bent.', true, 'Has your doctor cleared you for exercise? Stop if you feel pain, heaviness or leaking.'),
  ('letter-to-myself-at-9-months-m9', 'A letter to the woman you were on the day your baby was born.', '["Write a letter to yourself on the day your baby was born.", "Include what you wish that woman had known, what you now know, and what has surprised you most about yourself.", "Keep it — it will mean something different at 12 months, and again at 2 years."]'::jsonb, 'This is milestone documentation and emotional processing in one act.', false, null),
  ('write-down-my-anger-again-m9', 'A second timed rage journal — what''s shifted since month 5?', '["Set a timer for 10 minutes.", "Write every resentment and frustration, without stopping or editing.", "Compare what remains from your earlier journal, and what has shifted."]'::jsonb, 'The month-by-month comparison is one of the most honest records of postpartum experience available, and most valuable when kept long enough to see the arc.', false, null),
  ('see-an-old-friend-m9', 'Reaching out to someone from your pre-baby world — a strong predictor of postpartum wellbeing.', '["Reach out to someone from before the baby — not a fellow parent.", "Meet for coffee or lunch, or have a call longer than 10 minutes."]'::jsonb, 'Sustained non-parent friendships are among the strongest predictors of postpartum wellbeing across all the research.', false, null),
  ('chase-me-crawling-game-m9', 'A crawling chase game — the first spatial interaction game, with cardio thrown in for you.', '["Get on all fours and chase your crawling baby.", "Follow, let them escape, follow again.", "Add full sound effects."]'::jsonb, 'This is the first spatial interaction game for your baby, and your cardiovascular system benefits too — the ridiculousness is the point.', false, null),
  ('daily-story-time-m9', 'The same chair, same time, every day — a daily reading ritual, not a reading lesson.', '["Choose the same chair and same time every day, before nap or before bed.", "Sit baby in your lap with a book in front of you."]'::jsonb, 'You aren''t teaching reading — you''re building the pathways for language and narrative, and the lifelong association of closeness with learning.', false, null),
  ('how-s-our-team-doing-at-9-months-m9', 'A 45-minute relationship review at the point where fatigue usually runs deepest.', '["Spend 45 minutes with a specific agenda: what has been hardest? What have we done well? What do we want to do differently in the next 3 months?", "Approach it with kindness instead of defensiveness."]'::jsonb, 'The 9-month mark is when fatigue is deepest, and naming it together matters most.', false, null),
  ('agree-on-alone-time-m9', 'An explicit conversation about alone time, before anyone hits breaking point.', '["Have an explicit conversation: how many hours does each of you need weekly, doing what, under what conditions?", "Make a concrete arrangement from it."]'::jsonb, 'Most couples only have this conversation when someone is already at breaking point — doing it as proactive maintenance works better.', false, null),
  ('full-plank-if-ready-m10', 'Progressing to a full plank — but only once your midline check and knee plank say you''re ready.', '["Confirm your month 8 gap check showed the midline closing, and the knee plank has felt solid for several weeks.", "Hold a full forearm plank on your feet for 15 seconds, rest 45.", "Do 5 sets.", "Check for doming or scar pulling each time — if either appears, go back to the knee plank."]'::jsonb, 'Rushing a full plank before the abdominal wall is ready can make separation worse — these checks are what make progressing safe.', true, 'Has your doctor cleared you for exercise? Stop if you feel pain, heaviness or leaking.'),
  ('go-back-to-something-you-loved-m10', 'Returning, modified, to a sport or activity that was yours before pregnancy.', '["Book a session, contact a coach, or join a class for an activity you did before pregnancy — running, swimming, yoga, a sport.", "Return to it in a modified form."]'::jsonb, 'Returning to something that is yours, not postpartum-specific, is an identity recovery step as much as a physical one.', true, 'Has your doctor cleared you for exercise? Stop if you feel pain, heaviness or leaking.'),
  ('strength-workout-3-times-a-week-m10', 'A structured 3x-a-week strength programme — bodyweight and a band are enough.', '["Train 3 times a week with a structured programme.", "Focus on squats, hip hinges, rows, shoulder press, and core stability.", "Work with a trainer for initial programming if you have gym access, or use bodyweight and a resistance band at home."]'::jsonb, 'A structured programme three times weekly is appropriate for most women now.', true, 'Has your doctor cleared you for exercise? Stop if you feel pain, heaviness or leaking.'),
  ('check-your-posture-m10', 'A simple mirror check for the postural changes months of feeding and carrying cause.', '["Stand naturally in front of a mirror in side profile.", "Check: is your head forward? Are your shoulders rounded? Is your lower back excessively curved?", "If pronounced, book 4-6 physiotherapy sessions."]'::jsonb, 'Most mothers have developed significant postural changes from months of feeding, carrying, and device use — physiotherapy produces results self-correction can''t.', false, null),
  ('weekly-outdoor-time-alone-m10', 'One weekly outdoor movement session alone — the first thing mothers sacrifice, and worth protecting first.', '["Once a week, do physical activity outdoors, alone — a walk, jog, cycle, or swim.", "Protect this time rather than treating it as optional."]'::jsonb, 'The cumulative mental health benefit is substantial and sustained, and it''s usually the first thing mothers sacrifice when life gets busy.', true, 'Has your doctor cleared you for exercise? Stop if you feel pain, heaviness or leaking.'),
  ('join-a-group-again-m10', 'Rejoining a regular group — structure makes socialising possible when motivation alone doesn''t.', '["Rejoin or start something with regularity: a book club, running group, monthly dinner, professional network, or a new class."]'::jsonb, 'Social isolation beyond the newborn phase is a documented wellbeing risk, and structure makes socialising possible when motivation alone doesn''t.', false, null),
  ('set-a-body-goal-you-ll-enjoy-m10', 'A 3-month body goal about capability, not weight or shape.', '["Set a 3-month goal about capacity — a distance, a strength benchmark, a skill — not a weight or shape."]'::jsonb, 'The shift in framing, from correcting change to celebrating capability, is the shift in your relationship with your body.', false, null),
  ('what-surprised-me-about-motherhood-m10', 'Writing about what genuinely surprised you about motherhood — the love, the grief, the limits.', '["Write about what genuinely surprised you about motherhood, both positively and negatively.", "Focus on what you actually feel, not what you expected to feel."]'::jsonb, 'Most of us are surprised — by the size of the love, by grief for our former lives, by our own capacity, by our own limits.', false, null),
  ('furniture-walking-course-m10', 'A safe furniture circuit for your cruising baby — and your enthusiasm matters as much as the circuit.', '["Create a safe circuit using the sofa, coffee table, and a low chair in a loop.", "Get on the floor and move alongside your baby as they cruise, encouraging them with real enthusiasm."]'::jsonb, 'This is peak physical activity for your baby — matching their energy and showing delight in their effort matters enormously.', false, null),
  ('eat-together-m10', 'Eating the same meal together at the same table — the richest daily language environment there is.', '["Eat the same meal at the same time as your baby, with their version softer and unseasoned."]'::jsonb, 'The shared table is how food culture and mealtime ritual are transmitted, and more vocabulary occurs at family mealtimes than in any other daily context.', false, null),
  ('monthly-date-out-m10', 'A non-negotiable monthly date, with no parenting talk for the first 20 minutes.', '["Go out as a couple for 2-3 hours, monthly and non-negotiable.", "Hold off on parenting discussion for at least the first 20 minutes."]'::jsonb, 'Couples who maintain their relationships through the early years make this investment consistently, not occasionally.', false, null),
  ('talk-about-year-two-m10', 'Starting the conversation about year two — a second child, career, travel, family rhythm.', '["Start talking about the next year: a second child if relevant, career plans, home changes, travel, family rhythm."]'::jsonb, 'Future-orientation together rebuilds the sense of being partners in a shared project — a frame extended parenting stress erodes without deliberate maintenance.', false, null),
  ('work-toward-a-5km-walk-or-run-m11', 'Building toward a continuous 5km walk or run by month 12.', '["Set a month 12 milestone: walk or run 5 kilometres continuously.", "Extend your longest single session by about 10% each week to build toward it."]'::jsonb, 'Achieving a milestone that is yours, not labelled postpartum, is identity recovery made physical.', true, 'Has your doctor cleared you for exercise? Stop if you feel pain, heaviness or leaking.'),
  ('strength-workout-written-down-m11', 'A written 4-week strength cycle, including a deload week.', '["Week 1: 3 sets of 10.", "Week 2: 3 sets of 12.", "Week 3: 4 sets of 10 with 5-10% more resistance.", "Week 4: deload to 3 sets of 8, lighter.", "Log every session."]'::jsonb, 'This is progressive overload, the mechanism behind all strength adaptation, and the written record makes progress visible and the practice sustainable.', true, 'Has your doctor cleared you for exercise? Stop if you feel pain, heaviness or leaking.'),
  ('letter-to-your-baby-year-one-m11', 'A letter to your baby about their first year, sealed until their birthday.', '["Write to your baby about this first year — what you observed in them, what surprised you, what you hope for them, and how you felt becoming their mother.", "Seal it and open it on their first birthday."]'::jsonb, 'This is milestone documentation and emotional processing in one act, written for them to receive later.', false, null),
  ('write-down-my-anger-third-time-m11', 'Your third quarterly rage journal — what remains, and what has shifted.', '["Set a timer for 10 minutes.", "Write every resentment and frustration, without stopping or editing.", "Compare to what you wrote at month 9 — what remains, what has shifted."]'::jsonb, 'The month-by-month comparison is one of the most honest records of postpartum experience available.', false, null),
  ('pick-up-a-goal-for-yourself-m11', 'One personal goal for the next year — and a first step you commit to.', '["Name one thing you want to do in the next year that is yours, not as a mother or partner.", "Write it down and tell someone.", "Commit to a first step."]'::jsonb, 'One year into parenthood, it''s time to also parent yourself.', false, null),
  ('make-a-sleep-plan-m11', 'A concrete sleep change for month 11 — acknowledgement alone isn''t enough by now.', '["Ask whether sleep is actually improving, and if not, identify the structural barrier.", "Make one concrete change this month — night weaning, sleep training, a shift swap, or a catch-up weekend."]'::jsonb, 'Chronic deprivation at 11 months warrants a plan, not only acknowledgement.', false, null),
  ('see-and-celebrate-first-steps-m11', 'Celebrating first steps — and the weeks of smaller wins that led there.', '["When first steps happen, film it, call family, and celebrate it.", "Notice and celebrate the weeks before too — pulling up, cruising, standing unsupported for 3 seconds."]'::jsonb, 'Milestones are a season, not a moment.', false, null),
  ('let-baby-pick-the-book-m11', 'Letting baby choose the book — even the 40th reread of the same one.', '["Keep books at baby''s level, on a low shelf or in a basket.", "Let them pull a book and bring it to you.", "Read whatever they choose, without redirecting them."]'::jsonb, 'Reading the same book for the 40th time isn''t boring — it''s what learning looks like from the inside.', false, null),
  ('letter-to-each-other-year-one-m11', 'A year-one letter exchange — an annual review conducted with love, not defensiveness.', '["Each partner writes the other a letter covering: what I appreciate about you as a partner this year, what I''ve admired about you as a parent, and what I want for us next year.", "Exchange and read them together."]'::jsonb, 'This is the emotional equivalent of an annual review, conducted with love and without defensiveness.', false, null),
  ('honest-talk-about-closeness-m11', 'An honest conversation about physical intimacy — what''s returned, what hasn''t.', '["Talk honestly about physical intimacy: what has returned, what hasn''t, what feels different."]'::jsonb, 'Many couples need explicit permission to acknowledge that this area has required work — that acknowledgement is the beginning of addressing it rather than tolerating it in silence.', false, null),
  ('finish-the-5km-walk-or-run-m12', 'Completing your 5km goal — and setting the next one.', '["Walk or run 5 kilometres continuously, completing the goal you set at month 10.", "Set your next 3-month goal."]'::jsonb, 'The habit of setting a physical goal and following through, not the specific goal, is what you''re building — it belongs in year 2 and beyond.', true, 'Has your doctor cleared you for exercise? Stop if you feel pain, heaviness or leaking.'),
  ('what-my-body-did-this-year-m12', 'Five things your body did this year, and what it needs for the next.', '["Write 5 things your body has done in 12 months.", "Then write what it needs in the next 12 — rest, strength, flexibility, restoration, adventure, gentleness, challenge."]'::jsonb, 'That answer becomes the north star for year 2 — a conversation with yourself worth having annually.', false, null),
  ('test-your-pelvic-floor-m12', 'Functional pelvic floor tests at 12 months — common issues are not the same as normal ones.', '["Do 10 ten-second holds without breath-holding.", "Do 10 quick flicks.", "Jump without leaking.", "Walk briskly without urgency.", "See a women''s health physiotherapist if any test fails."]'::jsonb, 'This is not normal — it is common, and the distinction matters because it is fully treatable.', false, null),
  ('make-the-solo-walk-a-habit-m12', 'Making your weekly solo walk as non-negotiable as the baby''s nap schedule.', '["Protect your weekly solo outdoor walk as fiercely as the baby''s nap schedule."]'::jsonb, 'This isn''t a postpartum activity — it''s a permanent mental health practice you discovered this year. Carry it into every year that follows.', true, 'Has your doctor cleared you for exercise? Stop if you feel pain, heaviness or leaking.'),
  ('letter-to-myself-year-one-m12', 'A letter to the woman you were the day before your baby was born.', '["Write to the woman you were the day before your baby was born.", "Include what you want her to know, what she''s carried, what she''s discovered, and what she deserves to hear that nobody told her."]'::jsonb, 'This is the most important piece of writing this year — don''t skip it.', false, null),
  ('who-am-i-now-check-again-m12', 'Redrawing your identity map from month 6 — which identities grew, which faded.', '["Return to the month 6 identity map.", "Note which identities you''ve nourished and which faded.", "Draw the new map."]'::jsonb, 'The goal isn''t the same identity as before motherhood — it''s a full, integrated identity that includes motherhood without being consumed by it.', false, null),
  ('thankful-for-a-hard-year-m12', 'A gratitude list for what was hard this year, not what was easy.', '["Write a gratitude list for what was hard this year and what it gave you — the sleepless nights, the moments of rage, the love that surprised you."]'::jsonb, 'This is the hardest gratitude practice there is. Do it anyway.', false, null),
  ('one-promise-to-myself-for-year-2-m12', 'One non-negotiable self-care promise for year 2, shared with your partner.', '["Write one non-negotiable self-care commitment for year 2 — your solo walk, your journaling, your workout, your friend call.", "Share it with your partner."]'::jsonb, 'This replaces the weekly decision of whether to care for yourself with one standing commitment.', false, null),
  ('first-birthday-tradition-m12', 'Designing the first birthday as a ceremony for yourselves, not just for a baby who won''t remember.', '["Design the first birthday thoughtfully — a photo, a meal, a letter read aloud, a song.", "Mark what you have all become this year."]'::jsonb, 'You have raised a human being through their most vulnerable year on earth — that deserves marking with intention.', false, null),
  ('look-back-at-the-year-s-photos-m12', 'Looking through the year''s photos together, telling your baby their own story.', '["Look through the year''s photos with your baby on your lap.", "Point to people and places, name them, and tell the story aloud."]'::jsonb, 'The practice of telling your child their own story is one you can continue for their entire life.', false, null),
  ('story-time-now-a-habit-m12', 'Daily reading, now as automatic as feeding.', '["Keep a pile of books at reachable height.", "Read for about 10 minutes daily, as a habit requiring no willpower."]'::jsonb, 'You''re building the architecture for language and narrative, and the association of closeness with curiosity — those last a lifetime.', false, null),
  ('how-s-our-team-full-year-check-m12', 'A 90-minute full-year relationship review, scheduled before the birthday.', '["Spend 90 minutes together without baby, with a prepared agenda.", "Cover: what was hardest this year as a couple? What are we most proud of? What do we want to do differently? What do we want to protect in year 2?"]'::jsonb, 'This is the most important conversation of the year for your relationship.', false, null),
  ('date-night-on-the-birthday-m12', 'A birthday-weekend date night celebrating what you''ve become as parents and partners.', '["On or near the birthday, have dinner just the two of you.", "Acknowledge, deliberately, what you''ve become as parents and partners this year."]'::jsonb, 'You survived the hardest year most couples face, and often more than survived — that''s worth celebrating together.', false, null),
  ('pick-3-habits-to-keep-m12', 'Picking the 3 relationship habits from this year worth keeping permanently.', '["From this year''s practices — nightly debrief, weekly check-in, monthly date — pick the 3 that gave the most value.", "Write them down somewhere visible.", "Commit to them as permanent."]'::jsonb, 'Year 2 deserves the same intentional maintenance as year 1, and what worked shouldn''t need rediscovering.', false, null),
  ('foot-pumps-m1-v', 'Simple foot and ankle pumps — genuine blood clot prevention in the first weeks.', '["Lying down, flex and point both feet for 30 seconds.", "Circle each ankle 5 times in each direction.", "Repeat every 1-2 hours during the first week.", "Complete the full course of any prescribed blood-thinning injections or stockings even once you feel well."]'::jsonb, 'Blood clots are a genuine risk in the first 6 weeks postpartum — don''t skip this. Calf pain, swelling or warmth in one leg, or sudden breathlessness needs same-day attention.', false, null),
  ('daily-oil-massage-m1-v', 'A warming daily massage that supports circulation — just keep it away from your stitches.', '["Have 15 minutes of warm oil massage on your arms, legs and back.", "Use warm sesame oil, the traditional Ayurvedic choice.", "Keep oil and massage away from your stitches and perineum until they have healed."]'::jsonb, 'This is rehabilitation, not indulgence — it supports circulation, reduces stiffness, and calms your nervous system.', false, null),
  ('healing-foods-m1-v', 'Traditional postpartum foods that genuinely help — and why water matters even more with healing stitches.', '["Include gondh ke laddoo for tissue healing, ajwain water for digestion, methi for milk supply, and haldi doodh as an anti-inflammatory, alongside a balanced diet.", "Drink plenty of water — restricting it worsens constipation, which means straining on healing stitches, raises urine infection risk, and can reduce milk supply.", "If you had gestational diabetes or have diabetes, ask your doctor how many laddoos suit you."]'::jsonb, 'Traditional postpartum foods are nutritionally well designed and complement a balanced diet, and plenty of water matters even more while your stitches heal.', false, null),
  ('40-days-of-rest-m1-v', 'The traditional 40-day chilla is sound rest — paired with short, gentle walks from day one.', '["Rest from housework, chores and responsibilities, and delegate everything except recovering and feeding your baby.", "Take short, gentle walks from the first days after birth to help circulation and get your bowels moving."]'::jsonb, 'Rest from chores is genuinely good for you, and pairing it with gentle movement lowers your risk of blood clots, eases gas pain, and helps your bowels get moving.', false, null),
  ('walk-early-walk-gently-m1', 'Short, gentle walks from day one or two — and the sign that you''ve done too much.', '["Walk around the room, to the bathroom and back, starting from the first day or two after birth.", "Go a little further each day.", "Slow down if your stitches pull or your bleeding gets heavier after walking."]'::jsonb, 'This helps your circulation, lowers the risk of blood clots, gets your bowels moving and lifts your mood.', false, null),
  ('what-normal-bleeding-looks-like-m1-v', 'What normal post-birth bleeding looks like, and the signs that mean it isn''t.', '["Expect lochia (post-birth bleeding) to be heaviest and bright red for the first few days, then turn pinkish or brown, then yellowish-white, over about six weeks.", "Expect it to briefly get heavier when you feed or first stand up.", "Use pads, not tampons or menstrual cups, until your doctor clears you.", "Watch for soaking a pad in an hour, clots larger than a plum, a foul smell, or bleeding turning heavy and bright red again after settling — these are warning signs."]'::jsonb, 'Knowing what''s normal for your bleeding lets you spot the warning signs early instead of worrying unnecessarily or missing something real.', false, null),
  ('headache-after-an-epidural-m1', 'The specific headache that can follow an epidural or spinal, and why it needs treating, not enduring.', '["Watch for a severe headache starting between one day and one week after an epidural or spinal, worse sitting or standing, better lying flat, sometimes with neck stiffness, nausea or dislike of bright light.", "Tell your doctor rather than enduring it — an anaesthetist can treat it, often with an epidural blood patch.", "Seek urgent help for difficulty passing urine, loss of feeling or movement in your legs, severe back pain, or a headache that suddenly gets much worse."]'::jsonb, 'This is treatable, and any severe headache after birth also needs checking for high blood pressure.', false, null),
  ('when-your-milk-comes-in-m1-v', 'What to expect as your milk comes in, and the signs your baby is getting enough.', '["Expect colostrum for the first few days, then fuller milk around day two to five.", "Feed often, 8 to 12 times in 24 hours, and give plenty of skin-to-skin contact to help your milk along.", "Look for six or more wet nappies a day from around day five as a sign your baby is getting enough.", "If you''re worried, ask for a lactation consultant early rather than supplementing on a relative''s advice."]'::jsonb, 'Feeding often and skin-to-skin contact help your milk come in and keep up with your baby''s needs.', false, null),
  ('tell-your-birth-story-m1-v', 'Telling your birth story out loud, in your own words, to someone who just listens.', '["Tell one trusted person your birth story in your own words, without performing okayness.", "Ask them to simply listen, without advising or fixing anything."]'::jsonb, 'The story needs to leave your body through words before it can settle — this matters more, not less, if your birth was frightening or involved forceps, ventouse or a serious tear.', false, null),
  ('short-walk-m2-v', 'Starting a daily 10-minute flat walk — the goal is the habit, not the pace.', '["Walk for 10 minutes on flat ground, daily.", "Go outdoors where possible, for the sunlight and air."]'::jsonb, 'This month''s goal is simply the daily walk, not pace or distance — sunlight, air and gentle movement all support recovery.', false, null),
  ('plan-the-gap-before-your-next-baby-m2-v', 'Why the WHO recommends waiting at least two years before your next pregnancy.', '["Discuss contraception at your six-week check, choosing a method that suits breastfeeding.", "Confirm your chosen method is actually in place, since fertility can return before your periods do and breastfeeding alone isn''t reliable contraception."]'::jsonb, 'The WHO recommends waiting at least two years after a birth before trying again, to give your body time to recover and to lower the risks for you and your next baby.', false, null),
  ('check-your-blood-count-m2-v', 'Why to ask for a haemoglobin check at your six-week visit.', '["Ask for a haemoglobin check at or before your six-week visit.", "Continue any iron tablets you were prescribed.", "Include iron-rich foods — ragi, dal, green leafy vegetables, jaggery — with a squeeze of lemon to help absorption."]'::jsonb, 'Anaemia is very common among Indian women, and blood lost at birth can make it worse, slowing recovery and lowering mood.', false, null),
  ('if-you-had-gestational-diabetes-m2-v', 'The follow-up blood sugar test many women with gestational diabetes are never told about.', '["Ask for a fasting glucose test between about six and thirteen weeks after delivery, if you had gestational diabetes.", "Continue a yearly check, often an HbA1c test, afterward."]'::jsonb, 'Gestational diabetes usually resolves after birth, but it raises your risk of type 2 diabetes later — many women are never told to get checked.', false, null),
  ('hip-stretch-m3', 'A hip flexor stretch relevant for every mother, whatever the birth.', '["Half-kneel with one knee down, opposite foot forward.", "Shift your weight forward gently until you feel a stretch at the front of your back hip.", "Hold 30 seconds, then repeat on the other side."]'::jsonb, 'Pregnancy shortens the hip flexors regardless of delivery route, and prolonged sitting during feeding compounds it.', false, null),
  ('check-the-gap-in-your-tummy-m8', 'A simple self-check for the midline gap (diastasis) before starting plank or crunch work.', '["Lie on your back, knees bent.", "Place two fingers on the midline above your navel.", "Slowly lift your head and feel for a gap or soft tissue that sinks under pressure.", "See a women''s health physiotherapist before planks or crunches if the gap persists, or feels wider than 2 finger-widths or soft."]'::jsonb, 'This determines your core progression plan for months 9-12 — normal is under 2 finger-widths with firm tissue.', false, null),
  ('easy-plank-on-knees-m8', 'A gentle knee plank — the safe entry point to real plank work.', '["Forearms and knees on the floor, hips level.", "Hold 10 seconds, rest 30.", "Do 5 reps.", "Watch for any midline doming or coning — if you see it, return to dead bugs for 2 more weeks."]'::jsonb, 'This is the safe entry to plank work — don''t rush to a full plank before this feels solid.', true, 'Has your doctor cleared you for exercise? Stop if you feel pain, heaviness or leaking.'),
  ('full-plank-if-ready-m9', 'Progressing to a full plank — once your month 8 diastasis check shows the midline has closed.', '["Confirm your month 8 diastasis check showed midline closure.", "Hold a full forearm plank on your feet for 15 seconds, rest 45.", "Do 5 sets.", "Check for doming each time — continue the modified plank if not cleared."]'::jsonb, 'Rushing a full plank before the midline closes makes diastasis worse.', true, 'Has your doctor cleared you for exercise? Stop if you feel pain, heaviness or leaking.'),
  ('check-your-cut-every-day-m1', 'A daily wound check, and the difference between normal healing and a problem.', '["Once daily after bathing, gently pat your wound dry and check it.", "Expect mild bruising, numbness, or itching as normal.", "Watch for redness spreading beyond the scar line, warmth, swelling, discharge, separating wound edges, foul smell, or fever above 38°C.", "Call your doctor the same day if in doubt."]'::jsonb, 'Wound complications are far easier to treat early.', false, null),
  ('safe-way-to-get-out-of-bed-m1', 'The safe way to get out of bed that protects your incision from a sit-up''s full load.', '["Roll onto your side first.", "Push up sideways with your arms.", "Lower your legs to the floor.", "Use this method every time for at least six weeks, and teach your partner so they can remind you."]'::jsonb, 'This protects the incision from the full load of a straight sit-up.', false, null),
  ('fix-shoulder-pain-after-surgery-m1', 'Why your shoulder hurts after a caesarean, and what actually helps.', '["Lie on your left side with a pillow between your knees.", "Do slow, belly-led breathing.", "Add gentle shoulder rolls.", "Use a warm cloth on your neck."]'::jsonb, 'This pain is caused by residual gas in the abdominal cavity irritating the diaphragm — entirely normal, and it usually resolves in 5-7 days. Tell your doctor if it persists beyond 10 days.', false, null),
  ('hold-a-pillow-when-you-cough-m1', 'Holding a pillow against your incision whenever you cough, sneeze or laugh.', '["Hold a folded towel or pillow firmly against your incision whenever you cough, sneeze, or laugh.", "Keep a small pillow within reach wherever you sit."]'::jsonb, 'The sudden intra-abdominal pressure of a cough is significant, and unsupported coughing causes real pain and unnecessary strain on the healing wound.', false, null),
  ('nothing-heavier-than-baby-m1', 'The six-week lifting limit that''s most commonly ignored, and the most common cause of complications.', '["For the first six weeks, lift nothing heavier than your baby.", "Arrange help in advance for toddlers, shopping, and laundry baskets.", "Hold off on driving too, since emergency braking loads the incision — most doctors advise waiting around six weeks."]'::jsonb, 'This is the most commonly ignored surgical instruction and the most common cause of wound complications and hernia.', false, null),
  ('soft-belly-support-band-m1', 'A soft support band for your healing belly — support, not compression.', '["Wear a soft, non-compressive binder or well-wrapped muslin for 4-6 hours during waking hours only.", "Never wear it at night.", "Make sure it doesn''t press directly on the incision."]'::jsonb, 'This provides gentle support and proprioceptive feedback to your healing abdomen — quite different from a waist trainer.', false, null),
  ('walk-early-walk-often-m1', 'Getting up and walking early after a caesarean — one of the most important things for your recovery.', '["Walk short distances several times a day — to the bathroom, around the room, to the kitchen and back.", "Stand as tall as comfortable rather than hunching over the scar.", "On stairs, go slowly, one step at a time, holding the rail."]'::jsonb, 'Early walking lowers the risk of blood clots, helps trapped gas move, clears your chest and speeds healing — it will feel slow at first, and that''s expected.', false, null),
  ('take-your-pain-relief-on-time-m1', 'Taking your pain relief on schedule, not just when it gets bad.', '["Take the pain relief your doctor prescribed on schedule for the first several days, rather than waiting until the pain is bad.", "Check any medicine with your doctor.", "Tell your doctor if pain is getting worse rather than better, which can signal infection."]'::jsonb, 'Staying ahead of the pain makes walking, coughing and feeding far easier — commonly prescribed options like paracetamol are generally considered compatible with breastfeeding.', false, null),
  ('bowels-and-bladder-after-surgery-m1', 'Managing the trapped gas, constipation and bladder changes that are common after surgery.', '["Walk, which helps bowels and gas move most.", "Drink plenty of water and eat fibre, and ask your doctor about a stool softener.", "Hold a pillow against the scar when you go to the toilet.", "Tell your nurse or doctor if you can''t pass urine within a few hours of the catheter being removed, or if it burns or feels incomplete."]'::jsonb, 'Trapped gas, slow bowels and constipation are very common after a caesarean, caused by the surgery, pain medicines and moving less.', false, null),
  ('stitch-or-staple-removal-m1', 'Finding out what closed your wound, and when it needs removing.', '["Find out before leaving hospital whether your wound was closed with dissolvable stitches, or staples or non-dissolvable stitches.", "If staples or non-dissolvable stitches, note the date for removal, usually days 5 to 10, and where to go.", "Keep the appointment even if the wound looks fine."]'::jsonb, 'Leaving staples or non-dissolvable stitches in too long can cause marking and irritation.', false, null),
  ('headache-after-your-spinal-m1', 'The specific headache that can follow a spinal anaesthetic, and why it needs treating, not enduring.', '["Watch for a severe headache starting between one day and one week after your spinal, worse sitting or standing, better lying flat, sometimes with neck stiffness, nausea or dislike of bright light.", "Tell your doctor rather than enduring it — an anaesthetist can treat it, often with an epidural blood patch.", "Seek urgent help for difficulty passing urine, loss of feeling or movement in your legs, severe back pain, or a headache that suddenly gets much worse."]'::jsonb, 'This is treatable, and any severe headache after birth also needs checking for high blood pressure.', false, null),
  ('feeding-positions-that-protect-your-scar-m1', 'Feeding positions that keep your baby''s weight off your healing incision.', '["Try the football hold, with baby tucked along your side under your arm, or side-lying feeding in bed.", "If holding baby across your front, put a firm pillow over your lap first.", "Ask a nurse or lactation consultant to help set up the first few feeds.", "For skin-to-skin, lay baby high on your chest, above the scar, with a pillow over your lower belly."]'::jsonb, 'These positions keep your baby''s weight off the incision while it heals.', false, null),
  ('gentle-scar-care-first-try-m2', 'Your first, very light scar touch — just to establish the habit.', '["Once your doctor clears you at the 6-week check, touch the skin just above and below the scar with dry fingertips.", "Move the skin, not the scar itself, in gentle horizontal circles for 1 minute daily."]'::jsonb, 'Numbness, sensitivity, or feeling nothing at all are all normal — the goal this month is only to establish the habit.', false, null),
  ('squeezes-matter-for-you-too-m2', 'Why your pelvic floor needs work too, even though you didn''t deliver vaginally.', '["After clearance, begin gentle pelvic floor contractions: hold 3 seconds, release 6.", "Do 5 reps, twice daily."]'::jsonb, 'Nine months of carrying a growing uterus loads the pelvic floor whether or not a baby passed through it — a caesarean doesn''t exempt you.', false, null),
  ('move-without-hurting-the-scar-m2', 'Movement patterns that protect your scar now and your back for years.', '["Log roll to get up, rather than sitting straight.", "Bend at the knees rather than the waist.", "Keep objects close to your body when carrying.", "Exhale on any effort."]'::jsonb, 'These patterns protect the healing scar now and, once habitual, protect your back for years afterwards.', false, null),
  ('plan-the-gap-before-your-next-baby-m2-c', 'Why the uterine scar needs time before your next pregnancy.', '["Discuss contraception at your six-week check, choosing a method that suits breastfeeding.", "Confirm your chosen method is actually in place by month 3."]'::jsonb, 'A short gap between a caesarean and the next pregnancy is associated with a higher risk of the uterine scar separating, and the WHO recommends waiting at least two years.', false, null),
  ('ask-for-your-operation-notes-m2', 'Getting a copy of your operation notes — the key fact for any future pregnancy.', '["Ask your hospital for a copy of your operative notes, or at least a discharge summary recording the type of cut made in your uterus.", "Keep it with your health records."]'::jsonb, 'This largely determines whether a vaginal birth after caesarean (VBAC) could be an option for you next time, and most women never ask.', false, null),
  ('check-your-blood-count-m2-c', 'Why to ask for a haemoglobin check after a caesarean specifically.', '["Ask for a haemoglobin check at or before your six-week visit.", "Continue the iron tablets you were prescribed.", "Include iron-rich foods — ragi, dal, green leafy vegetables, jaggery — with a squeeze of lemon to help absorption."]'::jsonb, 'Blood loss during a caesarean is often higher than during a vaginal birth, and anaemia is already very common among Indian women.', false, null),
  ('if-you-had-gestational-diabetes-m2-c', 'The follow-up blood sugar test many women with gestational diabetes are never told about.', '["Ask for a fasting glucose test between about six and thirteen weeks after delivery, if you had gestational diabetes.", "Continue a yearly check, often an HbA1c test, afterward."]'::jsonb, 'Gestational diabetes is a common reason for a caesarean, and while it usually resolves, it raises your risk of type 2 diabetes later.', false, null),
  ('closeness-after-a-caesarean-m2', 'When and how closeness can resume after a caesarean.', '["Wait until your bleeding has stopped, you feel ready, and your doctor has checked you, usually around the six-week visit.", "Choose positions that keep pressure off your scar.", "Use a water-based lubricant if dryness is an issue from breastfeeding.", "Have contraception in place first.", "Raise any pain during sex with your doctor or a women''s health physiotherapist rather than enduring it."]'::jsonb, 'There is no deadline, and readiness is emotional as well as physical — pain during sex is treatable, not something to accept.', false, null),
  ('when-birth-didn-t-go-to-plan-m2-c', 'Why a caesarean deserves the same respect as any other birth, even when it didn''t feel like a choice.', '["Recognise that grief, disappointment or a sense of failure after a caesarean is common, especially an unplanned or emergency one.", "Tell your doctor if you keep reliving your birth, have flashbacks or nightmares, or avoid anything that reminds you of it.", "If you had a general anaesthetic and missed your baby''s first moments, ask your partner or the staff to tell you what happened, and look at any photos taken."]'::jsonb, 'A caesarean is major surgery undertaken to keep you and your baby safe, and recovering from it takes real strength — birth trauma is recognised and treatable.', false, null),
  ('scar-massage-3-directions-m3', 'A three-direction scar massage that prevents the adhesions that cause discomfort later.', '["With two fingertips, move the skin at and around the scar side to side, 30 seconds.", "Then up and down, 30 seconds.", "Then diagonally, 30 seconds.", "Do this daily, about 2 minutes total."]'::jsonb, 'The scar is still actively maturing for another 12-18 months, and this work now prevents the adhesions that cause discomfort and restricted movement later.', false, null),
  ('hip-stretch-extra-important-m3', 'The hip flexor stretch that matters even more after a caesarean.', '["Half-kneel, one knee down, opposite foot forward.", "Shift your weight forward gently.", "Hold 30 seconds each side."]'::jsonb, 'C-section mothers usually have more pronounced hip tightness from the surgical position and reduced early walking, so this is worth prioritising.', false, null),
  ('map-the-numb-spot-m3', 'Mapping the numbness around your scar — it usually shrinks, slowly.', '["With a light fingertip touch, map the area of numbness around your scar.", "Note where sensation begins and ends."]'::jsonb, 'Numbness above the scar is extremely common and rarely explained in advance — tracking it over months lets you see it shrinking, which it usually does, slowly.', false, null),
  ('watch-for-a-bulge-at-the-scar-m3', 'The warning signs of a hernia developing near your caesarean scar.', '["Watch for a soft bulge at or near the scar that gets bigger when you cough, lift or stand, and may disappear lying down.", "Get a doctor''s review if you notice this, even without pain.", "Seek urgent same-day attention if the bulge becomes suddenly painful, hard, or cannot be pushed back, especially with vomiting."]'::jsonb, 'Occasionally the abdominal wall near a caesarean scar weakens and a hernia develops — it''s not an emergency on its own, but it needs a doctor''s review.', false, null),
  ('scar-massage-deeper-now-m4', 'Progressing to firmer scar massage that shapes how the scar feels months from now.', '["Use two fingertips with meaningful but not painful pressure in all three directions.", "Add gentle circular work directly on the scar.", "Include the tissue 2cm around the scar, since fascia adheres over a wider area than the visible line.", "Do this for 3 minutes daily."]'::jsonb, 'This month''s work directly determines how the scar feels at month 12 and beyond.', false, null),
  ('reconnect-with-your-tummy-muscles-m4', 'Reconnecting to abdominal muscles that were surgically cut through — a step vaginal birth skips.', '["Lie on your back and place a hand on your lower belly.", "Try to draw it gently inward on the exhale.", "Keep practising even if you can''t feel it engaging yet — that''s normal at this stage."]'::jsonb, 'Your abdominal muscles were cut through and the nerve supply disrupted, so reconnecting to them takes deliberate work that vaginal delivery mothers usually don''t need.', false, null),
  ('scar-and-bad-posture-link-m4', 'How scar tightness pulls your pelvis out of alignment and causes back pain that looks unrelated.', '["Stand side-on to a mirror and check whether your lower back is excessively curved.", "If so, combine daily scar mobilisation with the hip flexor release."]'::jsonb, 'C-section scar tightness pulls the pelvis into an anterior tilt and can create lower back pain that seems unrelated to the surgery — treating the scar often resolves it.', false, null),
  ('massage-around-the-scar-m5', 'Expanding scar massage further out — fascia adhesions reach wider than the scar itself.', '["Work the tissue 3-4cm in all directions from the visible scar.", "Use a smooth round bottle or your knuckles for rolling pressure.", "Do this for 4 minutes daily."]'::jsonb, 'Fascia is a connected web, and adhesions felt at the scar extend into surrounding tissue in ways that affect bladder position, hip flexor tension, and lower abdominal sensation.', false, null),
  ('check-the-gap-after-surgery-m5', 'Checking the midline gap after a caesarean, where diastasis and scar tightness often combine.', '["Place two fingers on the midline above your navel.", "Lift your head slowly and feel for a gap or tissue that sinks.", "See a women''s health physiotherapist before any plank or crunch work if the gap exceeds two finger-widths."]'::jsonb, 'C-section mothers often have both diastasis and scar restriction together, and each makes the other harder to resolve.', false, null),
  ('bigger-circle-scar-massage-m6', 'Expanding scar massage further, in the most impactful window for this work.', '["Massage tissue 2cm above and below the visible scar line.", "Gently roll a smooth round bottle over the surrounding area with moderate pressure.", "Spend about 4 minutes total.", "Protect the scar from direct sun for the first year, since healing scars darken easily."]'::jsonb, 'This is the most impactful window for scar work — the tissue is still highly remodellable and responds well.', false, null),
  ('hip-stretch-deeper-m6', 'A deeper hip stretch that addresses the psoas tightness surgery and reduced walking leave behind.', '["Half-kneel with arms overhead.", "Add a gentle rotation toward the front knee.", "Hold 30 seconds each side."]'::jsonb, 'This addresses the deeper psoas, directly affected by both the surgical position and months of reduced walking — C-section mothers benefit disproportionately.', false, null),
  ('full-scar-massage-routine-m7', 'A full scar massage routine, now checking for the tight bands that cause low-belly pulling.', '["Use firm pressure in all three directions on the scar.", "Add circular work on the scar itself.", "Check for any tight bands running below the scar toward the pubic bone.", "Spend about 3 minutes daily."]'::jsonb, 'Those bands are the most common cause of the low-belly pulling sensation that many women describe at this stage and never mention to anyone.', false, null),
  ('tummy-exercises-step-by-step-m7', 'A more conservative core progression, because your abdominal wall was surgically divided.', '["Do dead bugs and bird dogs before attempting any plank.", "Only progress when you can perform 12 controlled reps with no doming and no pulling at the scar."]'::jsonb, 'Slower here produces better outcomes than pushing — your abdominal wall was surgically divided and needs the extra caution.', true, 'Has your doctor cleared you for exercise? Stop if you feel pain, heaviness or leaking.'),
  ('roll-and-press-the-scar-m8', 'Rolling and pressing out any remaining tight points in the scar.', '["Use a smooth rolling object over the broader scar area with moderate pressure.", "Add sustained thumb pressure on any remaining tight points, holding 30 seconds each.", "Spend about 4 minutes total."]'::jsonb, 'By month 8 the scar should be noticeably softer than at month 4 — if it isn''t, seek physiotherapy rather than continuing alone.', false, null),
  ('check-the-gap-again-m8', 'Rechecking the midline gap against your month 5 result.', '["Recheck your midline gap the same way as before.", "Compare it to your month 5 result.", "Book a women''s health physiotherapist this month if it''s unchanged since month 5."]'::jsonb, 'C-section mothers frequently see slower diastasis closure because the scar restricts the fascia''s ability to draw back together.', false, null),
  ('wake-up-the-numb-skin-m9', 'A simple sensory re-training routine for numb or hypersensitive scar skin.', '["Brush a piece of rough fabric across the scar and surrounding skin for 30 seconds.", "Then a soft cloth for 30 seconds.", "Then a fingertip for 30 seconds.", "Repeat three times daily."]'::jsonb, 'This re-educates the sensory nerves and is a genuinely trainable, reversible process that most women are never told about.', false, null),
  ('ready-to-run-check-tummy-and-scar-m9', 'A tummy-and-scar readiness check before you start running or jumping.', '["Do 10 jumps.", "Check afterwards for any pulling at the scar, doming along the midline, or lower back pain.", "If any sign appears, continue strengthening and retest in 6 weeks."]'::jsonb, 'C-section mothers need the abdominal wall to tolerate impact loading, a different readiness question from the pelvic floor one — both must pass.', true, 'Has your doctor cleared you for exercise? Stop if you feel pain, heaviness or leaking.'),
  ('keep-the-c-section-scar-soft-m10', 'Deciding whether to taper your scar massage — based on the tissue, not the calendar.', '["If the scar is soft, pale, flat and mobile with no tight bands, taper massage to three sessions weekly.", "If any tightness or pulling remains, continue daily."]'::jsonb, 'Taper because the tissue has changed, not because ten months have passed — that distinction matters.', false, null),
  ('lift-heavier-bit-by-bit-m10', 'Gradually adding heavier lifting back in, rather than jumping straight to it.', '["Add load gradually — a full laundry basket, a heavier toddler, shopping bags.", "Exhale on effort.", "Watch for any pulling at the scar."]'::jsonb, 'The abdominal wall benefits from deliberate progressive loading rather than a sudden return to heavy tasks.', true, 'Has your doctor cleared you for exercise? Stop if you feel pain, heaviness or leaking.'),
  ('check-the-scar-at-11-months-m11', 'An 11-month scar check — there''s still time for intervention to change the outcome.', '["Assess whether the scar is flat and supple, or raised and tight.", "Check for any persistent numbness above it.", "Consult your doctor if raised or tight — silicone gel sheeting and continued massage are the evidence-based options."]'::jsonb, 'Full maturation takes up to 24 months, so intervention now still changes the outcome.', false, null),
  ('tummy-strength-test-m11', 'Two functional tests that tell you whether your abdominal wall has genuinely healed.', '["Hold a 30-second forearm plank, checking for no doming, no scar pulling, and no lower back compensation.", "Lift your baby from the floor and check you don''t need to brace awkwardly.", "Get a physio assessment if either test fails."]'::jsonb, 'These functional benchmarks matter more than any timeline, and passing them means the abdominal wall has genuinely healed rather than merely stopped hurting.', true, 'Has your doctor cleared you for exercise? Stop if you feel pain, heaviness or leaking.'),
  ('one-year-scar-check-m12', 'A full one-year scar assessment — midway through maturation, not the end of it.', '["Assess whether the scar is flat, pale, and supple.", "Check for raised tissue suggesting keloid or hypertrophic scarring.", "Check for tight bands pulling below the scar, or remaining numbness.", "Document anything unresolved and bring it to your doctor."]'::jsonb, 'Full maturation takes up to 24 months — this is midway, not the end.', false, null),
  ('one-year-tummy-test-m12', 'One-year functional tests specific to recovering from a caesarean.', '["Hold a 30-second plank with no doming.", "Lift from the floor without bracing.", "Cough without scar pain.", "Reach overhead and check for no low-belly pulling.", "See a women''s health physiotherapist if any test fails."]'::jsonb, 'Surgical recovery genuinely takes longer, and needing more time at 12 months is not a failure.', true, 'Has your doctor cleared you for exercise? Stop if you feel pain, heaviness or leaking.'),
  ('warm-sitting-bath-m1', 'A warm sitz bath that reduces swelling and eases soreness — plain water is enough.', '["Fill a shallow basin or sitz bath attachment with comfortably warm, clean water.", "Sit for 10 minutes, twice daily, for the first two weeks.", "Pat dry gently afterward — never scrub.", "Ask your doctor first if you want to add turmeric or neem, since anything added carries some risk of irritation or infection."]'::jsonb, 'Plain water is what''s recommended and it''s enough — this reduces swelling, eases soreness and is genuinely soothing.', false, null),
  ('ice-pack-down-there-m1', 'Ice for the first 72 hours, then warmth — the right order for soft tissue healing.', '["In the first 48-72 hours, wrap crushed ice or a chilled pad in a clean cloth.", "Apply for 10 minutes on, 10 minutes off. Never apply ice directly to skin.", "Switch to warm sitz baths after 72 hours."]'::jsonb, 'Swelling and bruising are normal, and ice reduces both — ice first, then warmth, is the correct sequence for soft tissue healing.', false, null),
  ('rinse-bottle-routine-m1', 'A simple peri-bottle rinse that makes the first two weeks far more comfortable.', '["Fill a peri bottle with warm water.", "Rinse the perineal area every time you use the toilet.", "Pat dry front to back with a clean cloth."]'::jsonb, 'Urine on healing tissue stings considerably, and this routine reduces both discomfort and infection risk.', false, null),
  ('sit-on-a-soft-cushion-m1', 'A horseshoe cushion that keeps direct pressure off your healing perineum.', '["Sit on a soft cushion or a rolled towel arranged in a horseshoe, so there''s no direct pressure on the perineum.", "Feed lying on your side where possible."]'::jsonb, 'Direct perineal pressure during the first weeks slows healing and increases pain — this positioning is genuinely therapeutic, not just comfort.', false, null),
  ('check-your-stitches-m1', 'A daily stitch check, and the signs that mean something''s wrong.', '["Once daily after washing, check the perineal area with a hand mirror if you''re able.", "Expect mild swelling, bruising, and stitches gradually dissolving as normal.", "Watch for increasing pain after day 5, foul-smelling discharge, fever above 38°C, or wound edges separating.", "Call your doctor the same day if in doubt."]'::jsonb, 'Catching a problem early is far easier to treat than waiting.', false, null),
  ('help-for-your-first-toilet-trip-m1', 'Easing the anxiety of your first bowel movement after a vaginal delivery.', '["Support the perineum with a clean pad while you go, for comfort and reassurance.", "Never strain, and keep fibre and fluids high.", "Ask your doctor about a stool softener if it''s difficult."]'::jsonb, 'Stitches are very unlikely to tear — fear of it leads to constipation, which then causes the straining that actually hurts, so treating it early is worth doing.', false, null),
  ('take-your-pain-relief-m1', 'Taking your pain relief regularly in the first few days, rather than waiting it out.', '["Take the pain relief your doctor recommends, such as paracetamol, regularly for the first few days.", "Check any medicine with your doctor.", "See a doctor if pain around the stitches is getting worse rather than better, which can signal infection."]'::jsonb, 'Taking it regularly makes sitting, walking and feeding easier, and it''s generally considered compatible with breastfeeding.', false, null),
  ('bladder-and-piles-m1', 'Managing early bladder leaking and piles — both are common after pushing.', '["Pass urine within a few hours of giving birth, and tell your nurse or doctor if you can''t, or if it burns.", "Pour warm water over the area while you pass urine to ease stinging.", "Drink plenty of water and eat fibre, and use a cold pack wrapped in cloth for piles.", "Ask your doctor about a stool softener or a breastfeeding-safe soothing cream."]'::jsonb, 'Some leaking when you cough or sneeze is common early on and usually improves with pelvic floor exercises — piles are very common after pushing too.', false, null),
  ('if-you-had-a-third-or-fourth-degree-tear-m1', 'What to do if you had a third- or fourth-degree tear — common to not raise, but treatable.', '["Take the laxatives and any antibiotics you were prescribed.", "Keep your perineal hygiene routine going.", "Ask for a referral to a women''s health physiotherapist.", "Attend your follow-up appointment in the weeks after birth.", "Tell your doctor about any difficulty controlling wind or stool, or urgency getting to the toilet, at every visit until resolved."]'::jsonb, 'This is embarrassing to raise and very common not to, but it is treatable, and it matters for planning any future birth.', false, null),
  ('gentle-massage-first-try-m2', 'Your first gentle perineal massage, once your doctor has cleared you.', '["Once your doctor clears you, typically week 5-6, use clean hands and warm oil.", "Gently massage the perineal tissue externally in slow circles for 2 minutes.", "See a women''s health physiotherapist if any pain is present, rather than continuing through it."]'::jsonb, 'This begins to address scar tissue and restore elasticity.', false, null),
  ('start-squeezing-doctor-ok-d-m2', 'Your first pelvic floor contractions, once your 6-week check confirms you''re healed.', '["After your 6-week check confirms healing, imagine lifting and closing your pelvic floor.", "Hold 3 seconds, release 6.", "Do 5 reps, twice daily.", "Never push through pain or a heavy dragging sensation."]'::jsonb, 'Vaginal delivery involves direct stretching and often tearing of the pelvic floor, so rebuilding slowly matters.', false, null),
  ('signs-to-watch-for-m2', 'The prolapse warning signs that are common after vaginal birth but rarely discussed.', '["Watch for a heaviness or dragging in the vagina, a bulge you can feel, or difficulty inserting a tampon.", "Notice if symptoms worsen by evening or after standing.", "Book a women''s health physiotherapist this month if any sign is present."]'::jsonb, 'Prolapse is common after vaginal delivery, rarely discussed, and highly responsive to physiotherapy when caught early — noticing it is not alarmism.', false, null),
  ('when-birth-didn-t-go-to-plan-m2-v', 'Why a vaginal birth can still be frightening or traumatic, even when it''s assumed to be the ''easy'' kind.', '["Recognise that a vaginal birth can still be frightening or traumatic — a long labour, an emergency, forceps or ventouse, heavy bleeding, or an unexpected tear.", "Tell your doctor if you keep reliving your birth, have flashbacks or nightmares, or avoid anything that reminds you of it."]'::jsonb, 'Your feelings about your birth are valid whatever kind of birth it was — birth trauma is recognised and treatable.', false, null),
  ('gentle-massage-longer-m3', 'Extending perineal massage to 4 minutes, and beginning internal work if comfortable.', '["Massage with warm oil for 4 minutes, external and beginning internal if comfortable.", "See a women''s health physiotherapist if tightness persists, intercourse is painful, or you feel pulling at the scar."]'::jsonb, 'These are treatable conditions — you do not have to accept them as permanent.', false, null),
  ('squeeze-and-breathe-together-m3', 'Coordinating your pelvic floor lift with your breath, the way it works in real life.', '["Exhale as you lift your pelvic floor.", "Inhale as you release."]'::jsonb, 'This is how the pelvic floor works in real life, with the diaphragm, not against it — vaginal delivery often disrupts this coordination and it needs deliberate retraining.', false, null),
  ('inside-massage-m4', 'Internal perineal massage that''s evidence-based scar tissue management.', '["With clean hands and warm oil, apply gentle pressure at the vaginal opening, moving gradually deeper.", "Hold moderate downward pressure for a minute.", "Move slowly side to side.", "Seek guidance from a women''s health physiotherapist if the tissue feels tight or painful."]'::jsonb, 'This is evidence-based scar tissue management.', false, null),
  ('build-squeeze-stamina-m4', 'Building pelvic floor stamina — training whichever is weaker, endurance or fast response.', '["Do 8-second holds, 10 reps.", "Then do 10 quick flicks."]'::jsonb, 'Vaginal delivery mothers often have good fast-twitch response but poor endurance, or the reverse — training both deliberately targets whichever is weaker.', false, null),
  ('ready-for-closeness-again-m4', 'Why physical and emotional readiness for closeness are separate things, and both matter.', '["Remember that medical clearance at 6 weeks doesn''t mean you have to be emotionally ready too.", "Don''t push through or wait out painful intercourse — see a women''s health physiotherapist, since pain usually indicates scar tissue tightness or pelvic floor overactivity.", "Use a water-based lubricant if breastfeeding has made things drier."]'::jsonb, 'Pain during intercourse is treatable, not something to accept, and dryness from breastfeeding is not a sign anything''s wrong.', false, null),
  ('check-the-healing-at-5-months-m5', 'A 5-month healing check — treatment, not waiting, is what improves things now.', '["Assess whether the scar is soft and mobile, or tight and pulling.", "Check for numbness or a sharp sensation on touch.", "Check for discomfort during intercourse or when inserting a tampon.", "Get a physio referral if tightness persists, rather than waiting."]'::jsonb, 'At 5 months the scar is still remodelling and remains highly responsive to massage and physiotherapy — waiting does not improve it, treatment does.', false, null),
  ('squeeze-while-you-move-m5', 'Adding a pelvic floor lift to everyday movements, not just isolated exercises.', '["Exhale and lift your pelvic floor as you stand from a chair, lift your baby, or climb stairs."]'::jsonb, 'A pelvic floor that works in isolation but not under load will not prevent leaking during real life — this is the transfer point.', false, null),
  ('soften-the-scar-m6', 'A warm bath followed by gentle scar massage — a technique most women are never told exists.', '["Take a warm bath for 5 minutes first.", "Gently massage the scar tissue in small circles for 3 minutes with clean hands.", "Continue with external perineal massage using warm oil if comfortable and healed."]'::jsonb, 'This reduces the scar adhesions that cause long-term discomfort — most women are never told it exists.', false, null),
  ('test-before-jumping-or-running-m6', 'A simple jump-and-cough test before you progress to running or high-impact exercise.', '["Jump on the spot 10 times.", "Cough forcefully three times.", "See a women''s health physiotherapist before progressing to running or jumping if you notice any leaking, heaviness, or dragging.", "If not, begin gradual impact loading."]'::jsonb, 'This test is more informative than any timeline for deciding when you''re ready for impact exercise.', true, 'Has your doctor cleared you for exercise? Stop if you feel pain, heaviness or leaking.'),
  ('inside-massage-keep-going-m7', 'Continuing internal scar massage — by now the tissue should feel noticeably more pliable.', '["With warm oil, do internal massage with slow sustained pressure at any tight points for 5 minutes.", "Book a physio if the tissue isn''t noticeably more pliable than at month 4."]'::jsonb, 'By month 7 the tissue should be noticeably more pliable than at month 4 — if it isn''t, physiotherapy is the clear next step.', false, null),
  ('fast-and-slow-squeezes-m7', 'Combining slow holds and fast flicks in one session — the way your pelvic floor actually works.', '["Do 10 slow 8-second holds.", "Then 10 fast flicks.", "Then 5 more slow holds."]'::jsonb, 'This trains the pelvic floor the way it actually functions: sustained tone with rapid response when needed for a sneeze, cough, or lift.', false, null),
  ('check-the-signs-again-m8', 'Re-checking for prolapse signs, which often appear or worsen around 6-9 months.', '["Re-check for heaviness or dragging, a bulge, or symptoms worse by evening or after standing.", "Book a women''s health physiotherapist this month if any symptom is present, rather than monitoring further."]'::jsonb, 'Prolapse symptoms often appear or worsen around 6-9 months as activity and lifting increase — this doesn''t mean you did something wrong, it means the support needs strengthening.', false, null),
  ('tummy-and-squeeze-together-m8', 'Combining core and pelvic floor engagement on the same breath — the way they actually work together.', '["On the same exhale, engage your transverse abdominis and lift your pelvic floor.", "Hold 5 seconds, release fully.", "Repeat for 10 reps."]'::jsonb, 'These two systems work as a unit — training them together is what produces continence and support during real movement.', true, 'Has your doctor cleared you for exercise? Stop if you feel pain, heaviness or leaking.'),
  ('ready-to-run-check-this-first-m9', 'A running-readiness test before you lace up — leaking or heaviness means stop first.', '["Do 10 single-leg hops on each side.", "Do 10 jumps.", "Do 10 forceful coughs.", "Stop and see a physiotherapist first if you notice any leaking or heaviness.", "If cleared, begin with 1-minute jog intervals."]'::jsonb, 'Vaginal delivery mothers carry a higher risk of stress incontinence with impact, and returning to running before the pelvic floor is ready causes problems that take far longer to resolve than waiting would have.', true, 'Has your doctor cleared you for exercise? Stop if you feel pain, heaviness or leaking.'),
  ('check-the-healing-at-9-months-m9', 'A 9-month scar check — the point to stop self-managing if anything still isn''t right.', '["Check whether the scar is soft, pale and mobile with no pain on touch or during intercourse.", "Get a referral if any of those issues remain, rather than continuing to self-manage."]'::jsonb, 'Scar tissue continues remodelling for up to 24 months, so intervention now still changes the long-term outcome substantially.', false, null),
  ('squeeze-check-after-running-m10', 'A post-run check-in — your pelvic floor adapts to impact on its own timeline.', '["After each running or jumping session, check for any leaking, heaviness, or urgency.", "Increase running volume by no more than 10% weekly.", "Treat any symptom as a signal to reduce load rather than push through."]'::jsonb, 'The pelvic floor adapts to impact gradually and on its own timeline.', true, 'Has your doctor cleared you for exercise? Stop if you feel pain, heaviness or leaking.'),
  ('is-closeness-comfortable-now-m10', 'Checking in on whether closeness is comfortable now, ten months on.', '["Ask yourself honestly whether intercourse is comfortable now.", "See a physiotherapist if there''s persistent pain, rather than accepting it as the new normal."]'::jsonb, 'Persistent pain usually indicates scar tissue restriction or pelvic floor overactivity, and both respond well to targeted physiotherapy — many women never raise it, but it isn''t simply how things are now.', false, null),
  ('keep-the-perineal-scar-soft-m11', 'Deciding whether to taper your perineal massage — based on the tissue, not the calendar.', '["If the scar is soft, pale and painless, taper massage to twice weekly as maintenance.", "If any tightness remains, continue daily and get a physio assessment."]'::jsonb, 'Tapering because time has passed rather than because the tissue has changed is the common error here.', false, null),
  ('squeeze-while-lifting-heavier-m11', 'Engaging your pelvic floor during increasingly heavy everyday lifting.', '["Exhale and lift your pelvic floor as you lift your baby from the floor, carry shopping, or move furniture."]'::jsonb, 'This is what makes the pelvic floor genuinely functional rather than merely strong in isolation.', true, 'Has your doctor cleared you for exercise? Stop if you feel pain, heaviness or leaking.'),
  ('one-year-healing-check-m12', 'A full one-year healing check — your scar is only midway through remodelling.', '["Assess whether the scar is flat, pale, soft, and mobile.", "Check for pain on touch, during intercourse, or when using a tampon.", "Check for any remaining tightness or pulling.", "Document anything unresolved and raise it at your 12-month appointment."]'::jsonb, 'Scar tissue remodels for up to 24 months, so this is midway, not the end.', false, null),
  ('one-year-squeeze-test-m12', 'One-year functional pelvic floor tests — common but not normal, and fully treatable.', '["Do 10 ten-second holds without breath-holding.", "Do 10 quick flicks.", "Jump and cough without leaking.", "Run without urgency and check for no heaviness by day''s end.", "See a women''s health physiotherapist if any test fails."]'::jsonb, 'This is common but it is not normal, and it is fully treatable.', false, null)
) as v(id, short_description, steps, why_this, requires_doctor_clearance, clearance_copy)
where mother_activities.id = v.id;
